add(0, 'lesson', '서버가 한 번의 주행 상태를 만드는 과정',
  ['C++ 서버는 받은 입력과 지면·충돌 상태로 다음 차량 상태를 계산합니다.',
   '이 권에서는 함수의 역할을 구분하고 숫자로 결과를 설명하는 연습을 합니다.'],
  `서버를 이해한다는 말은 모든 파일을 외운다는 뜻보다, 관찰한 문제를 어느 책임과 연결할 수 있는지를 뜻합니다. 차가 멈췄다면 입력이 도착했는지, 안전 정지가 작동했는지, 구동력이 접지면에 전달됐는지부터 구분할 수 있어야 합니다. 이 프로젝트의 중심은 SimulationHost입니다. 이 객체가 틱마다 NPC와 외부 충돌체를 준비하고 VehiclePhysics에 계산을 요청한 뒤 새로운 상태를 발행합니다. Unreal은 그 결과를 받아 화면에 표현합니다. 교재의 코드는 현재 저장소에서 가져온 실제 조각이며, 숫자 예제는 실제 관측값과 계산을 위한 가정을 따로 표시합니다. 각 장에서 먼저 용어를 읽고 짧은 코드의 입력과 출력을 찾으세요. 그다음 설명을 덮고 계산이나 함수 찾기 문제를 풀어 보시면 됩니다. 아직 전체 물리 공식을 유도하지 못해도, 상태가 만들어지는 순서와 잘못된 가정을 찾는 능력부터 갖출 수 있습니다.`,
  [ref('host', 'SimulationHost::run_tick', 628, 678)], { imageKey: 'server_tick' });

add(0, 'table', '코드를 읽기 위한 기본 용어',
  ['단위와 역할을 적어 두면 비슷한 이름의 값을 혼동하지 않습니다.'],
  `틱은 시뮬레이션이 한 번 계산을 진행하는 단위입니다. 60Hz라는 설정은 시뮬레이션 시간 1초를 60번으로 나눈다는 의미이며, 어떤 상황에서도 실제 시간이 정확히 그 속도를 보장한다는 뜻은 아닙니다. 상태는 계산 시점의 위치와 속도 같은 결과를 묶은 값입니다. 입력은 사용자가 원하는 가속이나 조향을 나타내며, 원하는 결과와 실제 결과 사이에는 물리 계산이 있습니다. 콜백은 이벤트가 발생했을 때 실행하도록 미리 등록한 함수입니다. 비동기 호출이 등장해도 그 함수가 자동으로 별도 CPU 스레드에서 오래 계산해 준다고 생각하면 안 됩니다. 코드의 ownership은 누가 객체를 소유하고 언제까지 살려 두는가를 뜻합니다. 반면 이 프로젝트의 control lease는 어느 연결이 차량을 조작할 권한을 가지는가를 뜻합니다. 둘 다 소유라는 말을 쓰지만 객체 수명과 제어 권한이라는 다른 문제를 다룹니다.`,
  [ref('hosth', 'SimulationHostConfig', 32, 65), ref('lease', 'ControlLease', 49, 69)],
  { headers: ['용어', '뜻', '프로젝트 예'], rows: [
    ['tick', '한 번의 상태 계산', 'run_tick'], ['state', '계산 결과 묶음', 'VehicleState'],
    ['callback', '이벤트 시 실행할 함수', 'async_wait 인수'], ['lease', '입력 소유권의 유효 기간', 'ControlLease'],
  ] });

add(0, 'lesson', '프로그램의 시작점과 설정',
  ['main은 옵션을 읽고 run_simcore에 서버 구성을 넘깁니다.',
   '설정 파일의 숫자와 실행 옵션을 먼저 확인한 뒤 물리 코드를 읽습니다.'],
  `C++ 프로그램의 시작점은 main입니다. main.cpp에서 main을 검색한 뒤 parse_runtime_options와 run_simcore 호출을 찾아보세요. 명령줄 파서는 주소와 포트, 지도 경로, 주파수, 차량 설정 경로 같은 실행 조건을 해석합니다. run_simcore는 차량 설정을 읽고 지도와 교통망을 준비한 다음 서버 객체를 조립합니다. 여기서 설정의 의미를 놓치면 정상적인 차량별 차이를 물리 버그로 오해할 수 있습니다. 예를 들어 최대 속도와 질량을 바꾼 트럭이 세단과 같은 가속을 보이지 않는 것은 자연스럽습니다. 오늘은 옵션 파서의 모든 문자열 분기를 읽을 필요가 없습니다. 사용 중인 설정이 어떤 변수로 들어가서 SimulationHostConfig의 어느 필드로 옮겨지는지만 연결해 보세요. 잘못된 옵션이나 체크섬을 조용히 무시하는 대신 초기화 과정에서 거부하는 지점도 확인할 수 있습니다. 시작 단계의 실패와 주행 중 실패를 분리하면 로그를 읽는 범위가 크게 줄어듭니다.`,
  [ref('main', 'main', 432, 452), ref('main', 'run_simcore', 178, 215)]);

code(0, '실행 옵션을 호스트 설정으로 전달하는 코드',
  ['주파수와 세 가지 시간 제한은 호스트가 사용할 값으로 복사합니다.'],
  `첫 줄은 SimulationHostConfig 객체를 만듭니다. 이어지는 위치와 방향 필드는 차량이 시작할 좌표 기준을 결정합니다. physics_frequency_hz는 고정 계산 간격을 만드는 주파수입니다. command_timeout은 오래된 조작을 안전 정지로 바꾸는 기준이고, max_command_queue_age는 도착한 명령의 대기 지연을 검사하는 기준입니다. hard_command_timeout은 기존 연결의 제어권을 폐기하는 더 긴 제한입니다. 세 필드의 숫자가 모두 시간이라는 이유로 같은 기능으로 묶으면 안 됩니다. 입력이 아예 없어진 상황과 오래된 입력이 늦게 도착한 상황은 다른 검사로 처리합니다. 이 조각은 값을 전달하는 조립 코드이므로 실제 비교 연산은 다른 파일에 있습니다. 지금은 오른쪽 options의 값을 바꾸면 왼쪽 어느 필드에 반영되는지 설명해 보세요. 이어서 ControlLease를 읽을 때 각 제한을 어디서 사용하는지 찾으면 설정과 동작을 한 줄로 연결할 수 있습니다.`,
  'main', 'run_simcore', 321, 329);

add(0, 'lesson', 'SimulationHost의 조립 책임',
  ['물리 객체, 제어권, 교통 상태를 묶어 한 번의 틱을 진행합니다.',
   '네트워크 전송은 주입한 콜백을 통해 호출합니다.'],
  `조립이라는 말은 이미 존재하는 여러 기능을 한 실행 순서로 묶는다는 뜻입니다. SimulationHost가 모든 저수준 계산을 직접 구현하는 것은 아닙니다. 타이어 힘은 VehiclePhysics가 계산하고, WebSocket 바이트 전송은 WsServer가 수행합니다. 호스트는 어떤 입력을 적용할지와 언제 계산할지, 계산 결과를 어디로 보낼지를 연결합니다. main에서 callbacks.broadcast_world_state에 등록하는 람다는 서버의 상태 발행 요청을 WebSocket broadcast로 이어 줍니다. 이렇게 전송 함수를 밖에서 넣으면 실제 소켓 없이도 호스트 테스트가 상태 바이트를 받아 검사할 수 있습니다. 이것을 의존성 주입이라고 부르며, 이름보다 테스트에서 무슨 장점이 생기는지 설명하는 편이 중요합니다. 실제 실행에서는 소켓 콜백을 쓰고 테스트에서는 메모리에 받은 메시지를 해석합니다. 어느 쪽에서도 같은 run_tick이 실행되므로 단순 계산 함수만 확인하는 검사보다 실제 조립 흐름에 가까운 검사를 만들 수 있습니다.`,
  [ref('main', 'run_simcore', 299, 350), ref('hosth', 'SimulationHostCallbacks', 68, 73)]);

code(0, 'Asio 이벤트 루프의 실행',
  ['ioc.run은 준비된 타이머·통신 콜백을 실행하는 루프에 들어갑니다.'],
  `이 부분에서 shutdown_signals는 종료 신호를 감시하는 비동기 작업을 등록합니다. 람다가 오류 없이 호출되면 ioc.stop을 실행하여 루프 종료를 요청합니다. 마지막 ioc.run이 실제 이벤트 루프를 진행하는 호출입니다. 앞에서 async_wait나 async_accept를 호출했다고 해서 main 함수가 별도 물리 루프를 자동으로 만든 것은 아닙니다. 현재 main에는 하나의 io_context를 실행하는 한 번의 run 호출이 있습니다. 따라서 그 루프에서 실행하는 한 콜백이 긴 계산을 하면 같은 루프의 다른 통신과 타이머 콜백도 기다립니다. 지도 로더처럼 별도의 실행 경로를 쓰는 작업이 있다고 해서 NPC 검색까지 자동으로 병렬이 되는 것도 아닙니다. 이 차이를 이해하면 로컬 네트워크가 빠른데도 상태가 오래 멈추는 현상을 설명할 수 있습니다. 읽을 때에는 비동기라는 단어보다 실제로 어떤 스레드가 어떤 콜백을 실행하는지 찾아보세요.`,
  'main', 'run_simcore', 407, 413);

code(0, '다음 틱을 예약하는 타이머',
  ['예약 시각은 SimulationClock이 관리하고 콜백은 run_tick으로 이어집니다.'],
  `expires_at은 상대적으로 몇 밀리초를 더 기다리라는 값 대신 다음 마감 시각을 타이머에 넣습니다. async_wait에는 기다림이 끝났을 때 호출할 람다를 등록합니다. lifetime은 객체 수명이 끝난 뒤 오래된 콜백이 호스트를 건드리는 일을 피하기 위한 약한 참조입니다. operation_aborted는 타이머를 취소한 상황이므로 정상 종료나 리셋 과정의 일부로 처리할 수 있습니다. 이 코드 아래에는 다른 오류를 기록하는 분기와 run_tick 호출, 다음 예약이 이어집니다. 예약과 계산을 분리하면 고정 간격 계산, 종료, 취소를 각각 설명하기 쉽습니다. 하지만 타이머가 예약한 시각과 콜백이 실제로 실행된 시각은 다를 수 있습니다. 운영체제의 일정과 앞선 작업의 길이가 영향을 주기 때문입니다. 타이머는 늦어질 수 있다는 사실을 전제로 이후의 SimulationClock이 초과 시각을 처리합니다. 소스에서 타이머 등록 부분과 물리 수식을 같은 역할로 읽지 않는 연습을 하세요.`,
  'host', 'SimulationHost::schedule_tick', 607, 614);

add(0, 'lesson', '60Hz와 50km/h의 한 틱 이동',
  ['50km/h는 13.8889m/s이며, 60Hz 한 틱은 약 0.016667초입니다.',
   '직선·등속 가정의 한 틱 이동은 약 0.23148m, 즉 23.15cm입니다.'],
  `시간 간격 dt는 delta time의 약자로 두 계산 시점 사이에 진행시킬 시간을 뜻합니다. 현재 호스트는 dt_seconds를 1.0 나누기 physics_frequency_hz로 만듭니다. 주파수가 60이면 1초를 60등분하므로 dt는 약 0.016667초입니다. 속도 50km/h를 서버 단위로 바꾸려면 50에 1000을 곱하고 3600으로 나눕니다. 결과 13.8889m/s에 dt를 곱하면 약 0.23148m가 나옵니다. 이 값은 계산 연습을 위해 속도와 방향이 일정하다고 가정한 이동량입니다. 실제 update는 힘으로 속도를 바꾸고 충돌이나 지면 제한도 적용하므로 매 틱 똑같이 23.15cm 이동한다고 기대해서는 안 됩니다. Unreal의 기본 길이 단위 cm와 서버의 m를 연결할 때 100배 변환을 빠뜨리면 엄청난 오차가 생깁니다. 노트에 숫자만 쓰지 말고 각 중간 결과의 단위를 함께 쓰세요. 단위가 맞지 않으면 식이나 해석이 잘못됐다는 빠른 신호입니다.`,
  [ref('host', 'SimulationHost::run_tick', 665, 678)], { imageKey: 'server_tick' });

code(0, '실제 시간 지연과 시뮬레이션 시간',
  ['늦은 마감은 건너뛰지만 계산한 틱 수는 한 번만 증가합니다.'],
  `advance는 계산을 마친 실제 시각을 받습니다. tick_index를 하나 증가시키고 다음 마감 시각에 period를 더합니다. 완료 시각이 다음 마감보다 늦으면 놓친 주기의 수를 구해 마감을 미래로 이동합니다. 놓친 시간을 따라잡으려고 즉시 여러 물리 틱을 연속 실행하는 폭주를 피하기 위한 방식입니다. 중요한 결과는 실제 시간이 1초 지나도 서버가 60틱을 끝내지 못했다면 시뮬레이션 시간도 정확히 1초 진행하지 않을 수 있다는 점입니다. 이 설계는 부하가 생겼을 때 시뮬레이션이 느려질 수 있음을 받아들입니다. 반면 제어권 만료는 steady_clock의 실제 경과시간으로 판단하므로 긴 NPC 계산 동안에도 만료 기준은 지나갑니다. 고정 dt를 쓴다는 이유만으로 통신 지연이나 제어권 문제까지 사라지지는 않습니다. 초과 횟수를 볼 때 계산 정확도와 실시간 처리량을 별도 항목으로 생각해 보세요.`,
  'clock', 'SimulationClock::advance', 43, 54);

add(1, 'table', '연결 상태와 주행 허용 상태',
  ['소켓 연결, 새 Play 확인, 유효한 제어 입력은 서로 다른 단계입니다.'],
  `TCP와 WebSocket 연결이 성공했다는 사실만으로 차량이 즉시 움직여도 된다고 판단할 수는 없습니다. 서버는 클라이언트의 Hello와 프로토콜 정보를 확인하고, 새 Play가 어떤 시뮬레이션인지 구분한 다음 제어 입력을 받습니다. awaiting_reset은 해당 실행의 초기화가 필요하다는 뜻이고, awaiting_control은 유효한 명령을 기다리는 상태입니다. active는 현재 제어와 생명주기 조건이 주행을 허용함을 뜻합니다. safe_stop에서는 오래된 입력을 계속 유지하지 않도록 안전 입력을 적용합니다. 같은 Play에서 재연결한다고 매번 물리 위치까지 초기화하면 사고 직후 차량이 갑자기 출발 위치로 이동할 수 있으므로 연결 세션과 Play 식별자는 별도로 관리합니다. 상태 이름을 외우는 것보다 각 상태에서 어떤 명령이 허용되는지 읽는 편이 중요합니다. make_health_snapshot과 세션 처리 함수를 함께 찾으면 화면에 연결됨이라고 보여도 움직이지 않는 이유를 구분할 수 있습니다.`,
  [ref('host', 'SimulationHost::make_health_snapshot', 569, 605), ref('session', 'SimulationHost::handle_simulation_reset', 412, 575)],
  { headers: ['상태', '기다리는 것'], rows: [
    ['awaiting_reset', '새 시뮬레이션 초기화'], ['awaiting_control', '유효한 제어 명령'],
    ['active', '현재 조건에서 주행 허용'], ['safe_stop', '신선한 입력 또는 필요한 복구 절차'],
  ] });

code(1, '명령 순서와 클라이언트 시계 검사',
  ['중복·역순 sequence와 뒤로 가는 client_time을 거부합니다.'],
  `sequence는 같은 제어 세션에서 명령 순서를 구별하는 증가 번호입니다. 이미 받아들인 값보다 작거나 같은 번호가 오면 과거 명령이나 중복 명령으로 취급합니다. client_time_ns는 클라이언트가 기록한 시간이며, 이전보다 뒤로 가면 순서와 신선도를 믿기 어려워 거부합니다. 이 두 검사는 비슷해 보이지만 서로 다른 정보를 확인합니다. 새 번호를 붙인 명령도 잘못된 과거 시각을 가질 수 있고, 시각이 정상이어도 이미 처리한 번호일 수 있습니다. accept는 모든 검증을 통과하기 전에는 최고 sequence나 마지막 시간 값을 갱신하지 않습니다. 잘못된 패킷 하나가 이후 정상 명령까지 계속 거부하게 만들면 안 되기 때문입니다. 코드를 읽을 때 return이 어떤 상태 변경보다 먼저 나오는지 확인하세요. 이 패턴은 입력 검증이 있는 대부분의 서버 코드에서 유용합니다. 오류 메시지만 추가하는 일과 거부된 입력이 상태를 망가뜨리지 않게 하는 일은 구분해야 합니다.`,
  'lease', 'ControlLease::accept', 114, 121);

code(1, '250ms를 넘긴 입력의 SafeStop',
  ['유효 입력 이후 경과시간이 soft timeout보다 클 때 안전 정지를 시작합니다.'],
  `이 함수는 이미 안전 정지 상태이거나 아직 명령을 한 번도 받지 않았다면 새로운 만료 사건을 만들지 않습니다. 다음 비교에서 경과시간이 timeout 이하이면 false를 반환합니다. 기본 설정 250ms에서는 정확히 250ms인 순간까지 이 비교만으로 만료하지 않고, 그보다 커진 첫 검사 시점에 안전 정지로 전환합니다. 실제 검사 시점은 틱 실행 시각에 달려 있으므로 화면에서 정지가 보이는 순간이 정확히 250.000ms와 일치할 필요는 없습니다. SafeStop은 기존 세션 소유권을 유지합니다. 같은 소유자의 신선하고 순서가 맞는 입력이 돌아오면 accept가 안전 정지를 해제할 수 있습니다. 다른 클라이언트가 이 틈을 이용해 제어권을 가져갈 수는 없습니다. 호스트가 실제로 어떤 브레이크와 기어 값을 넣는지는 make_safe_stop_input을 추가로 찾아 확인하세요. 네트워크를 잠깐 놓친 상황을 완전한 세션 종료와 구분하기 위한 안전 단계라고 이해하면 됩니다.`,
  'lease', 'ControlLease::update_timeout', 155, 165);

code(1, '1000ms를 넘긴 제어권의 폐기',
  ['hard timeout은 소유 세션을 폐기하고 재연결을 요구하는 경계입니다.'],
  `hard timeout은 SafeStop보다 긴 시간으로 설정하며, 생성자도 두 제한의 순서를 검증합니다. 마지막 명령이 없거나 현재 소유 세션이 없다면 여기서 다시 폐기하지 않습니다. 유효한 소유자가 있고 경과시간이 hard_timeout보다 커지면 안전 정지 상태를 유지하면서 그 세션을 retired 목록에 넣습니다. active_key를 비우는 작업은 기존 명령이 뒤늦게 도착해 다시 차량을 움직이는 것을 막는 의미를 가집니다. 현재 기본값에서는 정확히 1000ms 이하를 통과시키고 초과 시점에 처리합니다. 호스트는 이 반환값을 보고 연결 종료 콜백도 호출합니다. 따라서 사용자가 본 reconnect required는 단순한 화면 안내가 아니라 서버가 기존 제어 연결을 더는 사용할 수 없다고 판단한 결과입니다. 잠깐의 soft timeout은 같은 소유자의 신선한 입력으로 회복할 수 있지만, hard timeout 이후에는 새로운 연결에 맞춘 절차가 필요합니다. 이 차이를 질문받으면 소켓 재접속과 물리 리셋을 같은 말로 답하지 마세요.`,
  'lease', 'ControlLease::update_hard_timeout', 170, 180);

add(1, 'lesson', '100ms 큐 나이의 의미',
  ['서버 수신 간격에서 클라이언트 명령 시각의 간격을 뺀 값으로 추가 지연을 추정합니다.',
   '서버와 클라이언트의 절대 시계를 직접 빼는 계산은 사용하지 않습니다.'],
  `서로 다른 컴퓨터의 절대 시계는 기준점이 다를 수 있습니다. 그래서 이 코드는 현재 서버 시각에서 클라이언트의 시간 값을 바로 빼지 않습니다. 직전에 받아들인 명령과 새 명령 사이에서 서버가 느낀 경과시간과 클라이언트가 기록한 경과시간을 각각 구합니다. 예를 들어 서버 수신 간격이 150ms인데 클라이언트 명령 간격은 16ms라면 추가 대기 추정은 134ms입니다. 기본 100ms보다 크므로 거부합니다. 서버 수신 간격 120ms, 클라이언트 간격 40ms라면 추정은 80ms여서 이 검사만으로는 거부하지 않습니다. 이 값은 완벽한 네트워크 편도 지연 측정값은 아닙니다. 클라이언트 일시 정지와 수신 처리 지연, 큐가 쌓인 방식의 영향을 받는 추정입니다. 처음 받아들이는 명령은 비교할 이전 수신 시각이 없으므로 이 차이 검사를 건너뜁니다. 규칙의 한계를 이해해야 이 숫자를 핑이나 왕복 지연과 혼동하지 않습니다.`,
  [ref('lease', 'ControlLease::accept', 118, 132)]);

code(1, '경과시간 차이로 추가 대기를 계산하는 코드',
  ['음수 차이는 0으로 처리하며 한계를 초과한 명령만 거부합니다.'],
  `server_elapsed는 두 서버 수신 시각의 차이입니다. client_elapsed는 새 명령에 들어 있는 클라이언트 시각에서 마지막으로 인정한 명령의 클라이언트 시각을 뺀 값입니다. 두 값 모두 duration으로 만들어 단위를 맞춥니다. 서버 쪽 시간이 더 길게 흘렀다면 차이를 대기 지연으로 추정하고, 그렇지 않으면 0을 사용합니다. 음수 지연을 만들어 다른 검사를 상쇄하지 않도록 하는 선택입니다. 마지막 비교는 estimated_queue_age가 max_queue_age보다 클 때만 거부합니다. 기본 설정에서 100ms와 같다면 이 비교는 거짓이며 100ms를 넘으면 참입니다. 작은 차이처럼 보이지만 경계값 회귀 테스트에서는 정확히 확인해야 합니다. 이 코드는 서버가 받은 새 명령을 실제 적용할지 결정하는 부분입니다. 전송 큐를 줄이는 코드와 역할이 다르므로 이 검사만 추가해 오래된 상태가 쌓이는 문제를 모두 해결했다고 생각하면 안 됩니다.`,
  'lease', 'ControlLease::accept', 123, 132);

add(1, 'lesson', 'WebSocket 상태 큐와 밀림',
  ['생산 속도가 소비 속도보다 빠르면 대기 데이터가 늘어납니다.',
   '주행 상태는 오래된 대기 상태 대신 가장 최근 상태를 남깁니다.'],
  `큐는 아직 처리하지 못한 데이터를 순서대로 보관하는 구조입니다. 상태를 초당 60개 생성하는데 어떤 연결이 초당 20개만 전송할 수 있다면 매초 40개씩 대기가 늘어날 수 있습니다. 모든 상태를 차례로 보내는 정책에서는 연결 자체가 살아 있어도 사용자가 몇 초 전 위치를 보게 됩니다. 이 프로젝트의 일반 상태 broadcast는 전송 중인 메시지 하나와 가장 최근 대기 메시지 하나를 보관합니다. 새 상태가 오면 아직 쓰지 않은 대기 상태를 교체하므로 지연이 끝없이 커지는 것을 제한합니다. 이런 생산자와 소비자 속도 차이를 다루는 정책을 backpressure 또는 밀림 제어라고 부릅니다. 다만 모든 종류의 메시지를 마음대로 교체할 수 있는 것은 아닙니다. 초기 Hello와 생명주기 메시지처럼 전달 순서가 중요한 제어 과정은 별도로 다룹니다. 또한 서버 큐를 작게 유지해도 이벤트 루프 자체가 오래 막히면 최신 상태를 만들고 보내는 일부터 늦어집니다. 큐 정책과 계산 예산을 함께 봐야 합니다.`,
  [ref('ws', 'WsSession::send_binary', 66, 98), ref('wsh', 'WsSession', 37, 67)]);

code(1, '최신 대기 상태 하나를 유지하는 코드',
  ['쓰기 중인 앞 메시지는 보존하고 뒤의 대기 상태만 바꿉니다.'],
  `write_in_progress가 참이면 비동기 쓰기가 이미 어떤 버퍼를 사용하고 있다는 뜻입니다. 큐 크기가 두 개 이상이라면 앞에는 진행 중 메시지, 뒤에는 아직 보내지 않은 상태가 있습니다. 새 메시지를 back에 대입하면 대기 상태만 최신값으로 교체할 수 있습니다. 전송 중 메시지까지 바꾸거나 지우면 네트워크 계층이 읽는 버퍼의 수명과 내용이 깨질 수 있습니다. 따라서 latest-wins를 구현할 때에는 무엇을 교체할 수 있는지 정확히 정해야 합니다. 코드 앞부분에서는 이미 닫히거나 닫기 요청을 받은 연결에 상태를 넣지 않습니다. 아래쪽에는 큐가 비었을 때 새 쓰기를 시작하는 처리가 이어집니다. 세 개의 상태 A, B, C를 종이에 써서 A를 쓰는 동안 B가 대기하고 C가 도착하면 어느 메시지가 남는지 추적해 보세요. 정답은 쓰기 중 A와 대기 중 C입니다. B를 버리는 판단은 시뮬레이션 입력을 버리는 판단과 다르다는 점도 구별하세요.`,
  'ws', 'WsSession::send_binary', 72, 80);

code(1, '비동기 쓰기의 버퍼 수명',
  ['람다는 session과 message를 완료 시점까지 보유합니다.'],
  `async_write는 호출한 순간에 모든 바이트 전송을 끝내는 함수가 아닙니다. 호출 뒤에도 네트워크 계층이 버퍼를 사용할 수 있으므로 메시지의 저장 공간을 완료 콜백까지 살려 두어야 합니다. 여기서는 write_queue의 앞 메시지를 shared_ptr로 받아 message에 보관하고, 람다 캡처에도 넣습니다. self는 세션 객체 자체가 쓰기 도중 사라지지 않도록 보유합니다. write_in_progress는 겹치는 쓰기를 시작하지 않도록 관리하는 상태입니다. 완료 콜백에 들어오면 먼저 이 플래그를 해제하고 오류 여부와 다음 큐 항목을 처리합니다. 이 조각에서 C++ 람다 캡처는 단지 짧게 함수를 쓰는 문법 이상의 역할을 합니다. 네트워크 작업의 수명과 객체 소유권을 드러내는 부분입니다. 소유권을 설명할 때 무조건 shared_ptr가 안전하다고 말하기보다, 이 버퍼가 어느 비동기 작업이 끝날 때까지 필요한지부터 설명해 보세요. 닫기 코드도 진행 중 버퍼를 함부로 제거하지 않는 이유가 여기에 있습니다.`,
  'ws', 'WsSession::do_write', 181, 187);

add(1, 'quiz', '제어권과 큐 나이 연습',
  ['마지막 유효 명령 이후 300ms가 지났고 hard timeout은 1000ms입니다.',
   '새 명령의 서버 간격은 150ms, 클라이언트 간격은 16ms입니다.'],
  `두 상황을 독립적으로 풀어 보세요. 첫 번째 상황에서는 마지막 유효 명령 뒤 300ms 동안 입력이 없었습니다. soft timeout 250ms와 hard timeout 1000ms를 사용할 때 어떤 상태가 되어야 하는지, 기존 소유권을 폐기해야 하는지 적으세요. 두 번째 상황에서는 순서와 세션이 모두 정상인 새 명령이 왔지만 서버에서 본 수신 간격과 클라이언트에서 기록한 명령 간격이 다릅니다. 큐 나이 추정값을 계산한 뒤 100ms 제한을 통과하는지 판단하세요. 마지막으로 WebSocket이 연결되어 있다는 사실만으로 두 상황을 정상 주행으로 취급해도 되는지 답해 보세요. 답을 쓸 때 연결됨, active, 신선함이라는 단어를 섞지 않는 것이 목표입니다. 첫 상황은 시간 경과에 따른 안전 상태 전환을 묻고, 둘째 상황은 실제로 도착한 명령을 받아들일지 묻습니다. 풀이를 보기 전 두 상황을 검사하는 함수 이름도 각각 찾아 적으면 상태 전환과 입력 검증의 차이가 더 분명해집니다.`,
  [ref('lease', 'ControlLease::update_timeout', 155, 181), ref('lease', 'ControlLease::accept', 123, 132)]);

add(1, 'answer', '제어권 연습 풀이',
  ['300ms 무입력은 SafeStop 대상이며 기존 소유권은 유지합니다.',
   '추가 대기 추정은 150−16=134ms이므로 큐 나이 검사에서 거부합니다.'],
  `첫 상황은 update_timeout이 안전 정지를 시작하지만 update_hard_timeout은 아직 소유권을 폐기하지 않는 구간입니다. 유효한 동일 소유자의 명령이 다시 오면 신선도와 순서 검사를 통과한 뒤 회복할 수 있습니다. 다른 소유자가 명령을 보내는 것은 같은 회복 경로가 아닙니다. 두 번째 상황의 estimated_queue_age는 134ms입니다. 100ms보다 크므로 해당 명령을 받아들이지 않습니다. 거부한 명령으로 마지막 수신 시각과 sequence를 갱신하지 않는다는 점도 중요합니다. 그렇지 않으면 오래된 명령이 계속 도착할 때 안전 제한을 계속 연장하는 문제가 생길 수 있습니다. WebSocket 연결 상태는 전송 통로가 유지된다는 정보이며, 현재 조작을 안전하게 적용할 수 있다는 보장은 아닙니다. 더 확실히 이해하려면 수신 간격을 116ms로 바꿔 계산해 보세요. 차이가 정확히 100ms이면 큐 나이 초과 비교는 거짓입니다. 이후에도 다른 검사를 통과해야 최종적으로 명령을 인정합니다.`,
  [ref('lease', 'ControlLease::accept', 114, 149), ref('lease', 'ControlLease::update_hard_timeout', 170, 180)]);

add(2, 'lesson', 'Unreal 지면과 서버 지면 데이터',
  ['Unreal이 지형의 충돌 표면을 측정하고 서버는 내보낸 지면 데이터로 계산합니다.',
   '서버가 에디터의 모든 메시와 삼각형을 매 틱 직접 읽지는 않습니다.'],
  `차량 시뮬레이션에는 타이어 아래의 높이와 표면 방향이 필요합니다. 사용자가 에디터에서 만든 지형을 서버가 자동으로 모두 아는 것은 아니므로 지면 측정과 데이터 내보내기 단계가 있습니다. 이 프로젝트는 Unreal 쪽에서 충돌 표면을 측정하고 MapPackage를 만들며 서버는 그 결과를 GroundQuery 인터페이스로 질의합니다. 지도 패키지에는 지면 높이만 있는 것이 아니라 충돌체와 일치 여부를 확인할 식별 정보도 있습니다. Bake를 다시 했을 때 서버가 어느 버전의 지면을 사용하는지 확인하는 이유가 여기에 있습니다. 화면에 보이는 보도와 서버 지면이 다르면 타이어가 떠 있거나 박히는 것처럼 보일 수 있습니다. 오늘은 지형을 새로 만들지 않고 내보낸 결과가 계산 입력이 된다는 경계만 이해하세요. GroundQuery가 반환하는 위치와 normal, 재질 배율이 이후 서스펜션과 마찰 계산에 어떤 영향을 주는지 이어서 읽으면 클라이언트와 서버의 책임을 분명히 설명할 수 있습니다.`,
  [ref('map', 'RuntimeMapPackage', 46, 55), ref('ground', 'GroundHit', 60, 74)], { imageKey: 'suspension' });

code(2, '불변 지면 스냅샷의 형태',
  ['shared_ptr<const ...>로 읽는 동안 바뀌지 않는 질의 객체를 공유합니다.'],
  `RuntimeMapPackage는 지도 ID와 충돌 체크섬을 지면 및 충돌 질의 객체와 함께 보관합니다. shared_ptr는 여러 소유자가 같은 객체 수명을 공유할 수 있다는 뜻이고, const는 이 경로로 객체 내용을 수정하지 않겠다는 뜻입니다. 지도 재로딩을 구현할 때 물리 계산이 읽는 배열을 그 자리에서 수정하면 한 틱 중간에 서로 다른 버전의 데이터를 섞을 수 있습니다. 이 프로젝트는 별도로 준비한 후보 패키지를 틱 경계에서 교체하는 방식을 사용합니다. 읽는 사람은 현재 스냅샷을 계속 사용할 수 있고, 교체할 후보는 미리 검증할 수 있습니다. 다만 const 포인터를 쓴다는 사실만으로 프로그램 전체의 모든 동시성 문제가 사라지는 것은 아닙니다. 포인터 교체 자체의 동기화와 실제 적용 시점을 함께 확인해야 합니다. 호스트의 queue_map_package_reload와 apply_pending_map_package_reload를 찾으면 준비와 적용을 나눈 경계를 볼 수 있습니다. 이것은 데이터 구조 하나의 선택이 계산의 일관성에 연결되는 사례입니다.`,
  'map', 'RuntimeMapPackage', 46, 52);

code(2, '격자 안의 삼각형과 보간 가중치',
  ['셀 내부 위치에 따라 삼각형 세 점과 가중치를 고릅니다.'],
  `높이 격자는 일정 간격으로 측정한 점들을 저장합니다. 차량이 언제나 측정점 위에만 서 있지는 않으므로 점 사이의 높이를 계산해야 합니다. 이를 보간이라고 합니다. 이 구현은 사각 셀을 두 삼각형으로 나누고 셀 안의 위치에 맞는 삼각형을 선택합니다. local_column과 local_row가 셀 안의 가로세로 비율이며, 발췌에서는 local_row가 더 작은 쪽 삼각형을 선택합니다. 예를 들어 가로 비율 0.75, 세로 비율 0.25라면 가중치는 0.25, 0.50, 0.25입니다. 세 가중치의 합은 1이고 각 꼭짓점 높이에 이 비율을 곱해 더합니다. 이것은 교육용 계산 예이며 실제 위치를 측정한 결과가 아닙니다. 아래 코드에서는 normal도 같은 비율로 합친 다음 다시 정규화합니다. 사각 셀의 네 값을 언제나 동일하게 평균하는 방식으로 해석하면 경계에서의 동작을 잘못 예상하게 됩니다.`,
  'height', 'HeightfieldGroundQuery::query_down', 499, 507);

add(2, 'table', '지면 질의가 돌려주는 정보',
  ['높이는 접지 위치를, normal은 표면 방향을 알려 줍니다.'],
  `normal은 표면에 수직인 방향 벡터입니다. 평평한 지면의 위쪽 normal은 ENU에서 대략 0, 0, 1이며 경사면에서는 수평 성분도 생깁니다. 길이를 1로 만드는 정규화는 방향을 유지하면서 크기의 영향을 제거하는 과정입니다. 서버는 타이어 힘을 표면 접선 방향으로 계산할 때 이 정보를 사용합니다. distance는 아래로 내린 질의의 시작점에서 표면까지의 거리입니다. 측정 거리가 허용 범위를 넘거나 위를 향하지 않는 표면이면 유효한 지면으로 사용하지 않을 수 있습니다. surface_material_id는 아스팔트나 저마찰 표면을 구별하는 식별자이며 friction_multiplier는 지형이 제공하는 배율입니다. 차량 자체 타이어 마찰계수와 결합하므로 같은 차도 표면에 따라 그립이 달라질 수 있습니다. 높이만 올바르면 지면이 완전히 맞는다고 생각하지 마세요. normal의 방향, 접지 여부, 적용한 재질도 함께 확인해야 경사와 미끄러짐을 설명할 수 있습니다.`,
  [ref('ground', 'GroundHit', 60, 74), ref('height', 'HeightfieldGroundQuery::query_down', 514, 539)],
  { headers: ['필드', '단위·형태', '용도'], rows: [
    ['point_enu', 'm', '표면 위치'], ['normal_enu', '단위 방향 벡터', '표면 방향'],
    ['distance_m', 'm', '질의 깊이 확인'], ['재질 ID·배율', '식별자·무차원', '마찰 조정'],
  ] });

code(2, '지면 범위를 벗어난 상태의 처리',
  ['중심이나 발자국의 한 축·한쪽 면이 지면을 잃으면 지원 범위를 벗어났다고 판단합니다.'],
  `지도 데이터의 범위와 실제 지형의 끝은 서로 다를 수 있습니다. Bake 범위가 너무 작으면 화면에는 도로가 이어져도 서버는 그곳의 지면을 모릅니다. 이 조건은 중심 질의가 없거나 유효한 지면 질의가 전혀 없거나, 차체 발자국에서 앞뒤 축 또는 좌우 한쪽 전체가 지면 범위를 잃었는지 검사합니다. 한 바퀴만 하중을 잃는 상황과 지도 경계를 넘어 지면 정보 자체가 없어지는 상황을 구별하기 위한 조건입니다. 이어지는 코드가 이전 지원 자세를 복구하는 이유는 현재 지면 기반 모델에서 무한한 추락을 계속 적분하지 않도록 하기 위해서입니다. 이 처리를 일반적인 절벽 낙하 물리라고 설명해서는 안 됩니다. 문제를 조사할 때 ground_coverage_limited가 켜졌는지 먼저 확인하면 맵 범위 문제와 실제 접지력 부족을 나눌 수 있습니다. 단순히 안전 조건을 제거하면 화면에서 경계는 사라져도 지하로 계속 내려가는 다른 오류를 만들 수 있습니다.`,
  'phys', 'VehiclePhysics::update', 1902, 1906);

code(3, '차량 입력의 범위 제한',
  ['가속·브레이크는 0~1, 조향은 -1~1이며 비정상 수치는 안전값으로 바꿉니다.'],
  `입력 값은 물리 수식에 들어가기 전에 유효 범위로 제한합니다. std::isfinite는 무한대와 NaN 같은 값이 아닌지 확인합니다. clamp는 최소값보다 작으면 최소값, 최대값보다 크면 최대값을 사용하는 함수입니다. 가속과 브레이크는 음수 입력이 필요하지 않으므로 0부터 1 사이로 제한하고, 조향은 좌우 방향을 표현하기 위해 -1부터 1을 사용합니다. 이 프로젝트의 공개 조향에서 양수는 왼쪽이며 내부 계산으로 넘어갈 때 BodyFrameAdapter가 필요한 부호 변환을 맡습니다. 입력 0.5가 곧 차체 방향 0.5도라는 의미는 없습니다. 정규화된 요구를 뜻하며 조향 최대각과 조향 속도 제한이 실제 바퀴 각도로 바꿉니다. 이런 범위 검사를 통신 파서가 했더라도 물리 경계에서 다시 확인하면 독립 테스트나 다른 호출 경로에서도 수식을 보호할 수 있습니다. 다만 범위 제한이 잘못된 입력의 원인을 숨길 수 있으므로 상위 계층의 거부 로그와 함께 읽어야 합니다.`,
  'phys', 'VehiclePhysics::set_input', 632, 637);

add(3, 'table', '입력·조향·차체 방향의 단위',
  ['공개 차량 좌표는 X 전방, Y 왼쪽, Z 위쪽입니다.'],
  `각도와 각속도는 이름이 비슷해서 자주 섞습니다. steering은 단위가 없는 입력이며 steering_angle은 바퀴가 꺾인 각도입니다. heading은 차량이 지도에서 어느 방향을 향하는지를 나타내며 degree로 공개합니다. yaw_rate는 1초에 차체가 얼마나 회전하는지를 나타내므로 rad/s입니다. 같은 steering_angle에서도 속도와 접지 상태가 바뀌면 yaw_rate가 달라질 수 있습니다. 위치 east와 north는 지도 ENU 기준이지만 linear_velocity_body는 차량 몸체 기준입니다. 차량을 돌려 놓으면 차체 전방 속도의 값과 지도 동쪽 속도의 값이 일치하지 않을 수 있습니다. 내부 평면 계산에는 오른쪽 양수 convention이 있어 공개 값으로 바꿀 때 부호 변환도 등장합니다. 소스에서 음수가 보인다고 오류로 판단하지 말고 해당 값의 좌표계와 단위를 옆에 적으세요. 이 작은 습관이 좌우 기울기 반전이나 후진 중 방향 오류를 조사할 때 시간을 줄여 줍니다.`,
  [ref('ph', 'VehicleInput', 31, 38), ref('ph', 'VehicleState', 74, 108), ref('frame', 'BodyFrameAdapter', 9, 36)],
  { headers: ['값', '뜻', '단위'], rows: [
    ['steering', '조향 요구', '없음'], ['steering_angle', '바퀴 조향각', 'rad'],
    ['heading', '지도 기준 방향', 'degree'], ['yaw_rate', '차체 회전 속도', 'rad/s'],
  ] });

add(3, 'lesson', '바퀴 접촉과 서스펜션',
  ['타이어 접점과 서스펜션 길이가 각 바퀴의 지지력을 결정합니다.',
   '접촉 플래그와 실제로 지탱하는 하중을 함께 확인합니다.'],
  `서스펜션은 바퀴와 차체 사이에서 길이가 변하면서 힘을 전달하는 구조입니다. 스프링은 압축한 길이에 따라 밀어내는 힘을 만들고, 댐퍼는 압축 길이가 변하는 속도에 저항합니다. 지면 질의가 표면을 찾았다는 사실만으로 타이어가 충분한 하중을 받는 것은 아닙니다. 차체가 비틀려 어떤 바퀴가 거의 늘어난 끝에 있다면 표면을 알고 있어도 실제 지지력은 아주 작을 수 있습니다. 이 프로젝트는 바퀴마다 접촉 상태와 길이를 따로 계산합니다. 네 바퀴가 항상 전체 무게를 정확히 네 등분한다고 가정하면 연석 대각선 걸침을 설명할 수 없습니다. evaluate_suspension은 1차원 스프링·댐퍼 계산을 제공하고, 차체의 높이와 기울기 및 접촉 제약은 상위 물리 흐름에서 결합합니다. 화면에 보이는 링크나 프레임 메시가 직접 이 힘을 계산하는 것은 아닙니다. 시각 부품이 움직이는 이유와 서버에서 지지력이 생기는 이유를 각각 설명해 보세요.`,
  [ref('suspension', 'evaluate_suspension', 43, 74), ref('phys', 'VehiclePhysics::update_wheel_contacts', 2094, 2120)],
  { imageKey: 'suspension' });

code(3, '스프링과 댐퍼 힘 계산',
  ['스프링 힘은 압축량에, 댐퍼 힘은 압축 속도에 비례합니다.'],
  `spring_force는 spring_rate에 양의 압축량을 곱합니다. spring_rate의 단위는 N/m이므로 압축량 m와 곱하면 힘 N이 됩니다. damper_force는 damping 계수 N·s/m와 압축 속도 m/s를 곱해 힘을 구합니다. 두 힘을 더한 뒤 0과 최대 허용 힘 사이로 제한합니다. 지면을 붙잡아 아래로 당기는 음의 타이어 지지력을 만들지 않도록 하는 하한입니다. 교육용으로 스프링 강성 30000N/m, 압축 0.10m, 감쇠 계수 3000N·s/m, 압축 속도 0.20m/s를 넣으면 각각 3000N과 600N, 합계 3600N이 됩니다. 같은 압축량이어도 빠르게 압축하는 순간에는 댐퍼 기여가 커집니다. 정지해 압축량이 변하지 않으면 댐퍼 힘은 0에 가까워집니다. 실제 설정값과 이 예제 숫자는 구별하세요. 현재 코드의 초기 접촉에서는 이전 접촉이 없으므로 압축 속도 계산을 별도로 처리해 갑작스러운 허위 감쇠 힘을 피합니다.`,
  'suspension', 'evaluate_suspension', 64, 73);

add(3, 'table', '1500kg 세단의 정지 하중 계산',
  ['계산 가정은 평평한 지면, 정지, 좌우 대칭이며 g=9.80665m/s²입니다.'],
  `질량 kg에 중력가속도 m/s²를 곱하면 무게 N을 얻습니다. 1500kg에 9.80665를 곱하면 약 14709.98N입니다. 이를 네 등분하면 3677.49N이지만 현재 세단의 설정은 앞축 정지 하중 비율 0.55입니다. 따라서 전체 무게의 55%를 앞축에, 45%를 뒤축에 배분한 단순 정지 예에서는 앞바퀴 하나가 약 4045.24N, 뒷바퀴 하나가 약 3309.74N을 지탱합니다. 이 계산은 정지 하중의 기준을 이해하기 위한 것입니다. 경사면과 가속, 좌우 회전, 서스펜션의 길이 차이, 차체의 별도 지면 접촉이 생기면 네 값은 달라질 수 있습니다. mg/4를 실제 매 틱의 강제 정답으로 사용하지 마세요. 설정 파일에서 mass_kg와 front_static_load_fraction을 찾아 직접 같은 계산을 해 보세요. kg과 N을 혼동하면 서스펜션 강성이나 타이어 마찰력을 대략 열 배 틀리게 해석하는 문제가 생깁니다.`,
  [ref('cpp/host/config/vehicle_sedan.cfg', 'front_static_load_fraction', 1, 66)],
  { headers: ['계산 항목', '식', '값'], rows: [
    ['전체 무게', '1500×9.80665', '14709.98 N'], ['균등 가정', 'mg÷4', '3677.49 N'],
    ['실제 앞축 비율 적용', 'mg×0.55÷2', '4045.24 N/바퀴'], ['실제 뒤축 비율 적용', 'mg×0.45÷2', '3309.74 N/바퀴'],
  ] });

add(3, 'lesson', '연석 정지 문제의 실제 재현값',
  ['네 하중은 약 7285.3, 790.4, 0.001, 4552.1N이었습니다.',
   '지도 범위 오류와 벽 충돌 없이 한쪽 후륜 하중이 거의 사라졌습니다.'],
  `이 숫자는 연습을 위해 만든 균등 하중이 아니라 실제 문제 로그를 재현한 회귀의 값입니다. 바퀴 인덱스 0부터 앞왼쪽, 앞오른쪽, 뒤왼쪽, 뒤오른쪽 순서입니다. 뒤왼쪽은 거의 0N인데 뒤오른쪽은 약 4552N을 받습니다. 당시 ground_coverage_limited는 꺼져 있었고 충돌 접촉 수도 0이어서 맵 경계나 벽에 막힌 상황과 구별할 수 있었습니다. 이전 구동 배분은 두 후륜 중 작은 마찰 여력으로 양쪽 토크를 함께 제한했습니다. 그 결과 접지된 뒤오른쪽도 유효한 힘을 내지 못해 전진 입력을 4초 줘도 이동이 0에 가까웠습니다. 회귀에서는 뒤축 최대 힘 약 0.0142N을 관측했습니다. 이 사례의 핵심은 키 입력과 속도만 보지 않고 실제 바퀴 하중과 힘을 함께 기록한 점입니다. test_reported_diagonal_curb_restart는 이 위치와 방향을 다시 만들어 수정이 같은 조건에서 작동하는지 검사합니다.`,
  [ref('coursetest', 'test_reported_diagonal_curb_restart', 550, 614), ref('worklog', '연석 걸침', 98, 132)]);

code(3, '저속 제동식 구동 보조의 토크 상한',
  ['약한 쪽 제동 반력과 강한 쪽 접지 여력 안에서 공통 반축 토크를 허용합니다.'],
  `두 바퀴에 같은 반축 토크가 걸리는 차동장치에서는 접지력이 작은 쪽이 전달을 제한할 수 있습니다. 현재 코드는 저속에서 약한 쪽 바퀴에 브레이크 반력을 주어 다른 바퀴가 접지력을 사용할 수 있도록 보조합니다. 첫 계산은 바퀴 한쪽에 사용할 수 있는 서비스 브레이크 토크 용량입니다. 다음 계산은 강한 쪽 접지 용량과 약한 쪽 접지 용량에 제동 용량을 더한 값 중 작은 것을 공통 한도로 택합니다. 마지막 clamp는 실제 요청 토크가 이 한도를 넘지 않게 합니다. 뒤에서 traction_control_brake_torque가 약한 바퀴의 잉여 구동을 상쇄하므로 없는 지면 힘을 만들어 주지 않습니다. 이 보조는 속도 1.5m/s부터 줄어들어 3m/s에서 꺼지며 일반 주행의 차동 잠금을 뜻하지 않습니다. 서비스 브레이크 입력은 구동 계산 자체를 억제하고 사이드 브레이크와 반대 회전 반축도 보조를 제한합니다. 안전 제약을 유지하면서 어떤 힘의 경로를 보완했는지 설명하는 것이 중요합니다.`,
  'phys', 'VehiclePhysics::update', 1094, 1103);

add(3, 'table', '연석 재출발 토크 손계산',
  ['정지·충분히 올라온 구동 요구를 가정하고 횡력과 휠 관성의 과도응답은 생략합니다.'],
  `세단의 최대 구동 요구 힘 6000N과 타이어 반지름 0.32m를 곱하고 두 바퀴로 나누면 반축당 960N·m입니다. 후륜 서비스 브레이크 비율은 1에서 앞축 비율 0.65를 뺀 0.35입니다. 18000N에 0.35를 곱하고 두 바퀴로 나눈 뒤 반지름을 곱하면 한쪽 제동 용량은 1008N·m입니다. 강한 뒤오른쪽의 접지 토크를 단순하게 계산하면 4552.1에 마찰계수 1.05와 반지름 0.32를 곱한 약 1529.5N·m입니다. 약한 쪽을 0으로 근사하면 공통 상한은 1008N·m이고, 요청 960은 그 안에 들어옵니다. 약한 쪽 브레이크가 구동을 상쇄하는 동안 강한 쪽만 실제 지면 힘을 전달할 수 있습니다. 이 수치는 실제 첫 틱 출력값이 아닙니다. 첫 틱에는 구동력 상승률과 휠 관성도 작용합니다. 교육용 가정을 밝히는 습관이 구현 설명의 정확도를 높여 줍니다.`,
  [ref('phys', 'VehiclePhysics::update', 1074, 1108), ref('cpp/host/config/vehicle_sedan.cfg', 'max_service_brake_n', 1, 66)],
  { headers: ['항목', '계산', '결과'], rows: [
    ['반축 요구 토크', '6000×0.32÷2', '960 N·m'], ['약한 쪽 제동 용량', '18000×0.35÷2×0.32', '1008 N·m'],
    ['강한 쪽 접지 용량', '4552.1×1.05×0.32', '약 1529.5 N·m'], ['공통 상한', 'min(1529.5, 0+1008)', '1008 N·m'],
  ] });

code(3, '속도가 올라갈 때의 출력 제한',
  ['힘만 일정하게 주면 요구 출력이 속도에 비례해 계속 커집니다.'],
  `출력 P는 힘 F와 그 방향 속도 v의 곱으로 이해할 수 있습니다. 같은 6000N을 속도 10m/s에서 쓰면 약 60000W, 30m/s에서 쓰면 약 180000W가 필요합니다. 실제 설정에는 최대 출력이 있으므로 속도가 높을수록 허용할 수 있는 구동 힘이 줄어들 수 있습니다. 발췌의 power_limited_drive_force는 최대 출력을 현재 속도로 나누며, 속도가 0에 가까울 때 분모가 지나치게 작아지지 않도록 최소값을 둡니다. available_drive_force는 설정된 힘과 출력으로 허용할 힘 중 작은 값입니다. 이후 앞뒤 속도 한계에서 더 가속하는 토크를 끕니다. 속도만 마지막에 강제로 잘라 놓고 휠 토크를 계속 주면 숨은 바퀴 회전이 쌓일 수 있기 때문입니다. 이 모델은 정교한 엔진 토크 곡선과 모든 변속단을 재현한 모델은 아닙니다. 현재 힘·출력·기어 제한이 어떤 현상을 표현하는지부터 설명하고 부족한 부분은 구체적으로 구분하세요.`,
  'phys', 'VehiclePhysics::update', 775, 782);

code(3, '기어와 브레이크가 구동 요구를 바꾸는 코드',
  ['기어 방향에 따라 전진·후진 요구의 부호를 정하고 브레이크 입력은 구동을 억제합니다.'],
  `desired_drive_force는 현재 기어 방향과 throttle, 허용 구동 힘을 곱한 요구값입니다. 앞에서 gear_direction이 Drive, Reverse, Neutral을 방향 부호로 해석하며 후진에는 별도 최대 힘과 속도 한계를 적용합니다. 브레이크가 입력되거나 해당 방향 속도 제한에 걸리면 요구를 0으로 바꿉니다. 그러나 힘 요구가 0으로 바뀌었다고 차량 속도가 그 순간 바로 0이 되는 것은 아닙니다. 관성과 마찰, 브레이크 힘이 이후 움직임을 결정합니다. 방향을 바꿀 때에도 기존 구동력을 먼저 줄이고 반대 방향 힘을 쌓는 구간이 이어집니다. 후진 구현을 단순히 위치 변화 부호를 뒤집는 작업으로 이해하면 휠 회전이나 충돌 상대속도가 맞지 않게 됩니다. 함수에서 desired_drive_force와 applied_drive_force_n_가 왜 별도 변수인지 찾아보세요. 원하는 힘과 실제로 이번 틱에 적용할 힘을 구분해 키보드 입력이 한 프레임 충격으로 바뀌는 것을 완화합니다.`,
  'phys', 'VehiclePhysics::update', 787, 792);

code(3, 'Ackermann 앞바퀴 조향각',
  ['동일한 순간 회전 중심을 향하도록 안쪽 바퀴가 더 많이 꺾입니다.'],
  `바퀴 두 개가 서로 떨어져 있으므로 원을 돌 때 안쪽 바퀴와 바깥쪽 바퀴는 다른 반경을 지나갑니다. 이를 반영하는 대표적인 조향 기하가 Ackermann입니다. centre_radius는 대표 조향각과 휠베이스로 계산한 중심 반경입니다. 각 앞바퀴의 좌우 위치 wheel_y를 반영해 개별 반경을 만든 뒤 atan으로 각도를 구합니다. 최소 반경 0.05는 분모가 지나치게 작아지는 상황을 막는 수치적 하한입니다. 이 계산은 바퀴가 어느 각도를 향하는지를 정하며 차체가 반드시 그 원을 그대로 따라간다는 보장을 주지 않습니다. 실제 차량 궤적은 이후 타이어 힘과 슬립에 영향을 받습니다. 여기서 좌우 바퀴 조향각이 다르다는 사실과 좌우 휠의 시각 회전이 엉뚱하게 어긋나는 버그는 다른 문제입니다. 교육용 자전거 모델에서는 양쪽 바퀴를 하나의 대표 바퀴로 합치지만 서버는 네 바퀴 값을 보유합니다. 함수에서 계산한 두 각도가 어느 WheelState에 기록되는지 이어서 찾아보세요.`,
  'phys', 'VehiclePhysics::update', 877, 886);

add(3, 'lesson', '같은 조향각과 속도별 주행 반경',
  ['교육식 R≈L/tanδ는 미끄럼이 작은 저속 기하를 설명합니다.',
   '50km/h, L=2.70m, δ=10° 가정에서는 필요한 횡가속도가 약 12.60m/s²입니다.'],
  `휠베이스 2.70m와 대표 조향각 10도를 교육용 자전거 모델에 넣으면 반경은 약 15.31m입니다. 이 원을 속도 50km/h, 즉 약 13.89m/s로 돈다고 가정하면 yaw rate는 v/R로 약 0.907rad/s이고 횡가속도는 v²/R로 약 12.60m/s²입니다. 단순 평지 마찰 한계를 μg로 비교하면 μ=1.05에서 약 10.30m/s²이므로 요구가 그보다 큽니다. 따라서 이 기하식만으로 해당 속도에서 완전한 무미끄럼 회전을 기대하기 어렵습니다. 이 예제는 실제 서버의 전체 차량 모델이나 시험 결과가 아니라 가정의 모순을 찾는 손계산입니다. 조향각을 속도에 따라 임의로 줄이는 제어와, 같은 바퀴 각도에서 힘의 한계 때문에 궤적이 달라지는 현상을 구분하세요. 계산기에서 tan 입력을 10rad로 넣지 않도록 각도 모드도 확인해야 합니다. 설명할 때 핸들 입력, 바퀴 각도, 차체 회전 속도, 실제 궤적을 각각 다른 값으로 말하면 오해가 줄어듭니다.`,
  [ref('phys', 'VehiclePhysics::update', 875, 888), ref('phys', 'VehiclePhysics::update', 1004, 1035)]);

code(3, '횡슬립 각도와 저속 정규화',
  ['타이어가 향한 방향과 접점이 실제 움직이는 방향의 차이를 계산합니다.'],
  `슬립 각도는 바퀴가 향하는 방향과 바퀴 접점의 실제 이동 방향 사이의 차이를 나타냅니다. 코드에서는 바퀴 좌표의 종방향 속도와 횡방향 속도를 이용해 atan2를 계산합니다. 정지 부근에서 종속도가 아주 작아지면 작은 횡속도 오차만으로 각도가 크게 변하므로 최소 기준 속도를 둡니다. 이것을 저속 정규화 또는 regularization이라고 부릅니다. 마찰을 없애는 의미가 아니라 수식이 정지 부근에서 과민하게 반응하지 않도록 만드는 방식입니다. 이어지는 corner_stiffness와 slip angle의 곱이 횡력 요구를 만들고, 실제 마찰 한계로 이를 제한합니다. 종슬립은 타이어 둘레 속도와 노면 방향 속도의 차이와 관련된 별도 값입니다. 출발 때 헛도는 현상과 옆으로 미끄러지는 현상을 같은 숫자 하나로 설명하지 마세요. 휠별 속도를 차체 중심 속도와 똑같다고 가정하면 회전 중 안쪽과 바깥쪽 접점 움직임을 잘못 해석할 수 있습니다.`,
  'phys', 'VehiclePhysics::update', 995, 1003);

code(3, '마찰 원 안의 종방향 여력',
  ['일반 주행은 횡력을 먼저 배분하고 남은 힘으로 가속·제동을 계산합니다.'],
  `friction_limit는 차량 타이어 마찰계수, 지면 재질 배율, 해당 바퀴 수직 하중을 곱한 값입니다. 평면 힘의 합력이 이 크기를 넘지 않도록 제한하는 생각을 마찰 원이라고 부릅니다. 이 조각은 횡력 제곱을 전체 한계 제곱에서 빼고 제곱근을 구해 남은 종력 여력을 만듭니다. 예를 들어 한계 4000N에서 횡력 3000N을 사용한다면 종력 여력은 sqrt(4000²−3000²), 약 2645.75N입니다. 가속 힘 4000N과 횡력 3000N을 각각 독립적으로 허용하면 합력은 5000N이 되어 한계를 넘습니다. 사이드 브레이크를 건 뒤 타이어는 별도의 종력 우선 처리로 이어집니다. 이 차이가 뒷바퀴를 잠그면서 횡그립을 잃는 동작을 표현합니다. 원이라는 그림은 이해를 돕는 근사이며 실제 타이어의 모든 비선형 특성을 뜻하지 않습니다. 상수를 조절할 때에도 힘 예산이 어떻게 배분되는지 먼저 확인해야 특정 상황만 좋아지고 다른 코너링이 깨지는 일을 줄일 수 있습니다.`,
  'phys', 'VehiclePhysics::update', 1029, 1035);

code(3, '바퀴 힘이 차체 회전을 만드는 연결',
  ['회전 모멘트를 yaw 관성으로 나누면 각가속도이며 dt를 곱해 회전 속도를 갱신합니다.'],
  `차체를 돌리는 힘의 효과는 힘이 작용하는 위치에 따라 달라집니다. 회전 중심에서 떨어진 타이어의 횡력은 회전 모멘트를 만들며, 코드에서는 바퀴별 위치와 힘을 합산해 total_yaw_moment를 구합니다. yaw_inertia는 차체가 수평 방향 회전 변화에 저항하는 관성입니다. 회전 모멘트 N·m를 관성 kg·m²로 나누면 각가속도 rad/s²에 해당하고, dt를 곱하면 회전 속도의 변화 rad/s가 됩니다. 교육용으로 모멘트 2850N·m와 관성 2850kg·m²를 가정하면 각가속도는 1rad/s²이고 60Hz 한 틱에서는 약 0.01667rad/s 증가합니다. 이는 실제 코너 한 장면의 측정 결과가 아니라 단위 연결을 위한 예입니다. 앞의 두 줄은 종횡 속도 갱신 결과를 저장합니다. 위치와 각도는 이 속도를 바탕으로 이어서 진행합니다. 조향 키가 heading을 직접 바꾸는 코드와 힘을 적분하는 코드가 어떤 차이를 만드는지 여기서 설명할 수 있습니다.`,
  'phys', 'VehiclePhysics::update', 1398, 1403);

add(3, 'lesson', '가속과 회전에 따른 하중 변화',
  ['지면 힘의 작용점과 차체 무게중심의 거리가 pitch·roll 모멘트를 만듭니다.',
   '손계산 하중 이동식과 실제 네 서스펜션 계산을 구분합니다.'],
  `가속할 때 차체 앞이 들리는 모습은 단순히 애니메이션 각도를 추가해서 설명할 수 있는 현상이 아닙니다. 접지면에서 전달하는 힘과 무게중심 사이의 높이 차이가 차체를 기울이는 모멘트를 만듭니다. 교육용 준정적 예로 질량 1500kg, 가속도 3m/s², 무게중심 높이 0.55m, 휠베이스 2.70m를 사용하면 앞뒤 하중 이동량 ma h/L은 약 916.67N입니다. 평지에서 앞축 하중이 이만큼 줄고 뒤축이 늘어난다고 근사할 수 있습니다. 실제 서버는 네 서스펜션 반력과 접점 힘의 모멘트를 결합하고 차체 roll과 pitch를 갱신합니다. 순간적인 감쇠 힘과 경사, 접촉 제약 때문에 위 준정적 숫자와 매 틱 값이 같지는 않습니다. roll은 좌우 기울기, pitch는 앞뒤 기울기라는 방향도 구분하세요. 같은 횡가속도라도 트럭과 세단의 높이와 관성이 다르면 기울기 반응이 달라질 수 있습니다. 표현 메시의 기울기와 서버가 계산한 물리 상태를 함께 확인해야 합니다.`,
  [ref('phys', 'VehiclePhysics::update', 1328, 1354), ref('phys', 'VehiclePhysics::update', 1830, 1861)], { imageKey: 'suspension' });

add(4, 'table', '선택한 차종이 바꾸는 물리 값',
  ['차종별 프로필은 외형과 별개로 질량·치수·출력·관성 등을 바꿉니다.'],
  `make_player_vehicle_parameters는 세단 설정을 기준으로 차종에 필요한 값을 바꿉니다. 경차는 질량과 휠베이스, 타이어 반지름과 출력 등을 줄이고, 트럭은 질량과 높이 및 관성을 키우면서 최대 조향과 속도 제한도 달리 둡니다. 오토바이는 single_track 플래그와 전용 균형 처리를 사용합니다. 따라서 모델 메시를 트럭으로 바꾸는 일과 물리 프로필을 트럭으로 바꾸는 일은 각각 확인해야 합니다. 표의 값은 현재 코드의 설정값이며 특정 제조사 차량을 계측한 사양이라고 말할 수는 없습니다. 차종별 차이를 설명할 때는 무겁다거나 빠르다는 감상보다 어떤 숫자가 가속과 회전을 바꾸는지 연결해 보세요. 동일한 힘에 대해 질량이 크면 가속이 작아지고, 회전 관성이 크면 동일 모멘트에서 각속도 변화가 작아집니다. 서스펜션도 질량 비율로 조정하는 부분이 있지만 그 자체가 실제 서스펜션 구조 전체를 재현하지는 않습니다.`,
  [ref('profile', 'make_player_vehicle_parameters', 29, 153)],
  { headers: ['차종', '질량', '휠베이스', '타이어 반지름'], rows: [
    ['세단 기본', '1500 kg', '2.70 m', '0.32 m'], ['경차', '1050 kg', '2.133 m', '0.275 m'],
    ['트럭', '6200 kg', '3.85 m', '0.390 m'], ['오토바이', '240 kg', '1.81 m', '프로필 설정 확인'],
  ] });

code(4, '오토바이의 별도 프로필',
  ['single_track은 두 축 중심의 접촉과 오토바이 균형 계산으로 연결됩니다.'],
  `오토바이는 일반 자동차의 네 접점을 좁게 줄인 모양만으로 충분히 설명하기 어렵습니다. 현재 프로필은 single_track을 켜고 질량 240kg과 짧은 휠베이스, 별도 조향 응답을 설정합니다. 물리 쪽에서는 앞뒤 중심선의 접촉을 사용하고 안쪽으로 기울어 균형을 잡는 제한된 보조를 적용합니다. 프로토콜에 네 휠 슬롯이 있다고 해서 실제로 독립적인 바퀴 네 개가 있다는 뜻은 아닙니다. 기존 상태 형식을 유지하기 위해 한 물리 축의 정보를 짝 슬롯에 나누어 표현하는 부분이 있습니다. 이 모델을 전문적인 오토바이 동역학이나 운전자 전체 균형 제어와 동일하다고 주장하면 안 됩니다. 타이어 형상, 정밀한 조향축 기하, 운전자 몸 이동 같은 현상에는 생략과 근사가 있습니다. 공부할 때에는 먼저 일반 차량과 다른 분기와 그 이유를 찾으세요. 이어서 motorcycle_balance 관련 함수를 읽으면 어떤 조건에서 보조를 줄이거나 해제하는지 확인할 수 있습니다.`,
  'profile', 'make_player_vehicle_parameters', 114, 121);

add(4, 'lesson', '차체 충돌 형상과 넓은 단계 검사',
  ['서버는 외형 메시 대신 회전 상자와 캡슐 같은 축약 충돌 형상을 사용합니다.',
   '먼저 가까운 후보를 줄이고 실제 겹침과 높이 구간을 검사합니다.'],
  `OBB는 방향을 가진 상자입니다. 차가 돌아가면 상자의 축도 함께 돌아갑니다. 현재 충돌 코어의 ObbPrism은 수평 회전 상자와 수직 높이 구간을 결합한 형상입니다. 보행자의 서 있는 몸에는 수직 캡슐 형상도 사용합니다. 복잡한 차체 메시의 모든 삼각형을 매번 비교하는 대신 단순 형상으로 계산량을 줄이는 선택입니다. broad phase는 많은 충돌체 중 가까울 가능성이 있는 후보를 빨리 줄이는 단계이고, narrow phase는 그 후보들이 실제로 겹치는지 확인하는 단계입니다. 코드에는 uniform grid 기반 후보 검색과 비교용 brute force 경로가 있습니다. 빠른 후보 검색은 결과를 바꾸기 위한 기능이 아니라 필요 없는 정밀 검사를 줄이기 위한 기능입니다. 디버그 상자의 위치와 크기를 외형과 함께 보는 이유는 이 축약 형상이 실제 접촉 판정 기준이기 때문입니다. 시각 모델의 범퍼가 닿지 않았는데 충돌한다면 메시보다 먼저 서버 상자의 기준점과 치수를 확인하세요.`,
  [ref('collisionh', 'CollisionWorld', 19, 65), ref('cpp/host/src/collision/collision_types.hpp', 'ObbPrism', 29, 43)],
  { imageKey: 'collision' });

code(4, '충돌 충격량의 질량과 회전 항',
  ['충격량은 상대 접촉 속도와 양쪽 질량·회전 관성의 영향을 받습니다.'],
  `충격량 impulse는 짧은 충돌 동안 힘을 시간에 대해 모은 양이며 단위는 N·s입니다. 물체의 선속도 변화는 충격량을 질량으로 나누어 구할 수 있습니다. 이 조각은 접점이 무게중심에서 얼마나 떨어져 있는지를 나타내는 arm과 회전 관성까지 분모에 포함합니다. 모서리 충돌이 중심 정면 충돌과 다른 회전을 만드는 이유입니다. 분자의 restitution은 반발 정도를 나타내고 normal_velocity는 충돌 법선 방향의 상대 접촉 속도입니다. 음수인 접근 속도를 해소하는 방향으로 양의 충격량을 계산합니다. 두 물체가 이미 멀어지고 있다면 위쪽 분기에서 불필요한 추가 반발을 주지 않습니다. 힘 N과 충격량 N·s를 구별하지 못하면 손상 기준이나 튕김을 해석할 때 단위를 잘못 비교하게 됩니다. 이 수식은 현재 평면 충돌 코어의 일부이며 복잡한 차체 변형을 동시에 해결하는 연속체 역학은 아닙니다. 실제 접촉 위치가 어느 식에 들어가는지 설명해 보세요.`,
  'collision', 'resolve_finite_proxy_contact', 595, 605);

code(4, '겹침을 반복해서 해결하는 충돌 루프',
  ['여러 접촉이 서로 영향을 주므로 제한된 횟수 안에서 해결을 반복합니다.'],
  `차가 벽과 다른 차량 사이에 끼면 접촉 하나를 해결한 결과가 다른 접촉에 영향을 줄 수 있습니다. 그래서 충돌 코어는 한 번의 검사로 끝내기보다 정해진 횟수 동안 겹침과 반응을 반복해서 조정합니다. 현재 kSolverIterations는 8입니다. 이 값은 무한 반복을 막고 한 단계의 계산량을 제한하는 역할을 하며, 모든 장면에서 완벽한 접촉 해를 보장한다는 뜻은 아닙니다. 각 반복에서 차체의 수평 범위를 다시 구하고 가까운 정적 후보를 찾습니다. 코드 아래에는 정밀 접촉과 동적 물체 처리가 이어집니다. 여기서 관통 보정을 무조건 크게 늘리면 서로 끼어 있는 물체가 과하게 튀거나 순간이동하는 다른 문제가 생길 수 있습니다. 속도 충격량을 조정하는 일과 이미 생긴 겹침을 분리하는 일도 개념상 다릅니다. 테스트에서는 최종 비관통뿐 아니라 유한한 속도와 제한된 이동량을 함께 확인하는 편이 안전합니다. 느린 장면을 조사할 때 후보 수와 반복 수를 구분해서 기록하세요.`,
  'collision', 'CollisionWorld::integrate_with_tire_supported_curbs', 1169, 1177);

add(4, 'lesson', '동적 proxy와 유한 질량 반응',
  ['proxy는 해당 틱에 사용할 외부 물체의 충돌 형상과 움직임을 담은 값입니다.',
   '질량이 있는 상대에게 반대 충격량을 적용해 함께 밀리거나 회전하게 합니다.'],
  `proxy라는 이름은 실제 게임 객체 전체를 충돌 코어에 넘기지 않고 필요한 정보만 대신 전달한다는 뜻입니다. 형상과 속도, 질량, 회전 관성, 마찰과 반발 같은 데이터가 들어갑니다. 고정 벽은 사실상 움직이지 않는 상대처럼 처리하지만 유한 질량 상대는 충격을 받은 뒤 속도와 회전이 변합니다. 교육용으로 회전을 생략하고 1500kg 자동차가 10m/s로 움직이다 같은 질량의 정지차와 완전 비탄성으로 부딪힌다면 운동량 보존의 공통 속도는 5m/s입니다. 실제 코어는 접점 회전과 마찰도 보므로 이 숫자가 모든 차끼리 충돌의 정답은 아닙니다. 중요한 것은 상대를 고정 벽처럼 취급하면 가벼운 사람이나 쓰러진 구조물에 부딪힐 때 차량이 과도하게 멈출 수 있다는 점입니다. 호스트는 계산 뒤 수정된 proxy를 각 런타임 객체에 반영합니다. 이미 진행한 물체 시간을 또 한 번 진행하지 않도록 pair solve와 이동 단계의 순서도 확인해야 합니다.`,
  [ref('cpp/host/src/collision/collision_types.hpp', 'KinematicCollisionProxy', 68, 110), ref('collision', 'apply_proxy_impulse', 394, 410)],
  { imageKey: 'collision' });

add(4, 'lesson', '구조물 손상과 보행자 반응의 범위',
  ['접촉 기록이 구조물 파손 상태와 보행자 몸체 반응을 갱신합니다.',
   '서버의 축약 몸체와 Unreal의 관절·메시 표현을 구분합니다.'],
  `구조물 손상은 단순히 화면에서 부스러기를 만드는 일과 서버 충돌 상태를 바꾸는 일을 함께 생각해야 합니다. 신호등이 넘어졌는데 서버에 수직 충돌체가 그대로 남으면 차가 보이지 않는 벽에 막힐 수 있습니다. StructureDamageRuntime은 접촉을 기록하고 파손 상태와 충돌 proxy를 갱신하는 역할을 합니다. 보행자는 PedestrianImpactState가 몸체 위치와 회전, 지면 또는 차량 위 지지 상태를 관리합니다. 이 클래스 주석처럼 서버가 계산하는 것은 축약한 골반·몸체 궤적이며 팔과 다리의 모든 관절을 동일하게 계산하는 것은 아닙니다. Unreal의 ragdoll이나 일어나는 자세 표현은 별도 책임입니다. 실제 인체 손상이나 모든 충돌을 정확히 예측하는 모델이라고 표현해서는 안 됩니다. 공부할 때에는 충돌 결과가 어느 데이터로 전달되고 다음 틱 충돌 형상에 어떻게 반영되는지 추적하세요. 화면 효과가 멋있어도 authoritative 형상이 맞지 않으면 주행 행동과 다음 접촉이 계속 어긋날 수 있습니다.`,
  [ref('cpp/host/src/collision/structure_damage.cpp', 'StructureDamageRuntime::record_contacts', 270, 306),
   ref('cpp/host/src/traffic/pedestrian_impact.hpp', 'PedestrianImpactState', 25, 57)]);

add(5, 'table', 'NPC의 경로·주행·표현 책임',
  ['NPC가 목적지를 선택하는 일과 매 틱 움직이는 일은 서로 다른 단계입니다.'],
  `NPC의 지능이라는 표현 안에는 여러 책임이 섞여 있습니다. route planner는 도로 그래프에서 목적지까지 이어지는 차선 순서를 고릅니다. lane follower는 선택한 경로의 어느 지점에 있는지 추적하고 속도 제한과 신호에 맞추어 진행량을 계산합니다. local bypass는 가까운 장애물을 돌아서 원래 길로 합류할 짧은 후보를 만듭니다. presentation은 계산된 위치와 방향으로 메시와 바퀴를 보여 줍니다. 따라서 NPC가 벽 앞에서 정지했다고 해서 운전자 애니메이션부터 수정할 필요는 없습니다. 경로가 없는지, 우회 후보가 모두 막혔는지, 충돌 뒤 운행 불가 상태인지부터 구분해야 합니다. 현재 NPC는 플레이어의 엔진과 네 바퀴 힘 계산을 각각 실행하는 구조가 아닙니다. 경로 기반 운동과 제한된 가속·회전, 유한 질량 충돌 반응을 결합한 축약 모델입니다. 같은 자동차 외형을 사용한다고 내부 계산도 완전히 같다고 설명하면 안 됩니다. 각 책임의 입력과 출력을 자신의 말로 한 문장씩 적어 보세요.`,
  [ref('planner', 'NpcRoutePlanner::shortest_route', 70, 117), ref('follower', 'NpcLaneFollower::step', 551, 628),
   ref('npc', 'SimulationHost::prepare_lane_npc', 1066, 1100)],
  { headers: ['책임', '질문', '찾을 심볼'], rows: [
    ['경로 선택', '어느 차선을 거칠까요?', 'shortest_route'],
    ['경로 추종', '이번 틱 얼마나 갈까요?', 'NpcLaneFollower::step'],
    ['근거리 우회', '장애물 옆으로 갈 수 있나요?', 'plan_npc_local_bypass'],
    ['화면 표현', '상태를 어떻게 보여 줄까요?', 'ASimCoreNpcPresentationActor'],
  ] });

code(5, '최단 경로의 비용 갱신',
  ['현재까지의 길이에 다음 차선 길이를 더하고 더 짧은 경로를 보관합니다.'],
  `그래프는 연결 관계를 표현한 자료구조입니다. 여기서는 차선이 정점에 해당하고 successors가 다음으로 갈 수 있는 차선 연결을 나타냅니다. shortest_route는 방문하지 않은 후보 중 누적 비용이 가장 작은 차선을 골라 이웃을 갱신하는 방식입니다. 발췌 첫 줄은 다음 차선들을 순회합니다. 막힌 차선이나 이미 방문한 차선은 건너뜁니다. candidate는 현재 최소 비용 best와 다음 차선 길이의 합입니다. 기존 경로가 없거나 새 값이 더 작으면 비용을 바꾸고 predecessor에 이전 차선을 저장합니다. 목적지에 도착하면 predecessor를 거슬러 올라가 실제 차선 순서를 복원합니다. 이 비용은 거리이며 신호 대기 시간이나 운전자 성향까지 모두 포함한 최적 주행 시간은 아닙니다. std::map의 차선 ID 순서를 사용하는 이유는 같은 비용의 후보를 처리할 때 순서를 안정적으로 만들기 위해서입니다. 입력 그래프와 막힌 차선 목록이 같은 경우 선택의 재현성을 설명할 수 있어야 합니다.`,
  'planner', 'NpcRoutePlanner::shortest_route', 106, 114);

add(5, 'table', '차선 길이로 최단 경로를 손계산하기',
  ['교육용 그래프입니다. A 다음에는 B 또는 C가 있고 둘 다 D로 연결됩니다.'],
  `교육용으로 A 길이 20m, B 35m, C 50m, D 25m라고 가정하겠습니다. 실제 planner는 시작 차선 비용도 포함하므로 A의 초기 비용은 20입니다. A를 처리하면 B는 55, C는 70이 됩니다. 그중 작은 B를 처리하면 D 후보는 80입니다. C를 처리해서 얻는 D 후보는 95이므로 기존 80을 유지합니다. 결과 차선 순서는 A, B, D입니다. 이제 B를 blocked_lanes에 넣으면 A에서 B로 확장하는 분기를 건너뛰고 A, C, D를 선택할 수 있습니다. 길이가 늘어도 통행 가능한 연결이 남아 있으면 목적지에 도달합니다. C도 함께 막으면 목적지를 연결할 수 없어 결과가 없습니다. 실제 도로에서 B 차선의 일부만 막힌 경우에는 그래프 전체에서 B를 제외하는 판단과 차선 안에서 짧게 비켜 가는 판단을 구별해야 합니다. 이 예제는 알고리즘의 비용 전파를 배우기 위한 가정이며 현재 맵의 차선 ID나 측정 거리를 뜻하지 않습니다.`,
  [ref('planner', 'NpcRoutePlanner::shortest_route', 81, 114)],
  { headers: ['상태', 'B 비용', 'C 비용', 'D 비용'], rows: [
    ['A 처리 뒤', '55m', '70m', '미정'], ['B 처리 뒤', '55m', '70m', '80m'],
    ['C 처리 뒤', '55m', '70m', '80m 유지'], ['B가 막힌 경우', '제외', '70m', '95m'],
  ] });

code(5, '신호 앞 정지점을 만드는 추종 코드',
  ['초록 신호가 아닌 접근 차선에서는 정지선 여유를 남긴 목표점을 계산합니다.'],
  `경로를 찾았더라도 신호를 무시하고 곧바로 목적지까지 이동해서는 안 됩니다. follower의 이 분기는 신호가 있는 차선과 아직 통과를 확정하지 않은 정지선을 확인합니다. green 검사 결과가 거짓이면 차선 끝에서 clearance를 뺀 위치를 정지 목표로 사용합니다. progress_m_보다 뒤에 있는 위치로 되돌리지 않도록 최댓값을 취하며, 여러 정지 이유 중 더 가까운 목표를 고릅니다. 다음 remaining은 현재 경로 진행량부터 목표까지의 거리입니다. braking_envelope는 그 거리 안에서 멈출 수 있도록 원하는 속도를 낮추는 계산입니다. 그 아래에서 가속도 또는 제동 가속도와 dt를 이용해 현재 속도가 한 번에 변하는 양을 제한합니다. 실제 플레이어의 네 바퀴 타이어 힘으로 감속하는 과정과는 구성이 다릅니다. 오늘은 정지선의 거리 단위가 m이고 속도의 단위가 m/s인지 확인하세요. 빨간불에서 정지 위치가 어긋나면 신호 색뿐 아니라 진행량과 차량 앞쪽 길이, 여유 거리도 살펴봐야 합니다.`,
  'follower', 'NpcLaneFollower::step', 612, 621);

code(5, '근거리 우회 후보의 폭과 길이',
  ['후보는 옆 이동량·전환 길이·좌우 방향을 달리하며 도로와 충돌을 검사합니다.'],
  `최단 경로가 도로망 전체의 연결을 다룬다면 근거리 우회는 현재 장애물 주변에서 차체가 지나갈 곡선을 만드는 문제입니다. 발췌는 0.75m부터 0.5m 간격으로 옆 이동 후보를 넓히는 반복입니다. 같은 이동량에도 전환 길이를 세 종류로 바꾸고 좌우를 모두 시도합니다. 최소 회전 반경이 큰 차량은 같은 옆 이동을 위해 더 긴 전환 공간을 요구합니다. 후보를 만들었다고 바로 운행하지는 않습니다. 이어지는 코드에서 차체 폭과 길이를 포함한 이동 구간, 지면과 도로 범위, 주변 물체를 검사해야 합니다. 후보 한 개 안에도 여러 지점의 검사가 들어가므로 후보 수만 보고 계산이 가볍다고 판단하면 안 됩니다. 모든 후보가 실패하는 좁은 도로가 오히려 비싼 입력이 될 수 있습니다. 이것은 제한된 후보를 평가하는 계획기이며 운전자 시야 영상을 이해하는 학습 모델이 아닙니다. 성공 경로가 존재해도 현재 후보 집합이나 안전 여유 안에서는 찾지 못할 수 있다는 한계가 있습니다.`,
  'local', 'plan_npc_local_bypass', 191, 200, { imageKey: 'npc_bypass' });

code(5, '후진 탐색을 다음 틱으로 나누는 커서',
  ['한 후진 거리에서 우회가 실패하면 다음 거리만 저장하고 반환합니다.'],
  `커서는 여러 번의 작업 사이에서 현재 어디까지 검사했는지 기억하는 값입니다. next_reverse_probe_m은 다음에 확인할 후진 거리입니다. 이 조각에서는 현재 requested 위치를 가정해 차선 변경과 근거리 우회 가능성을 검사합니다. 두 검사가 실패하면 요청 거리를 0.5m 늘리고 남은 범위 안인지 기록한 뒤 함수에서 나옵니다. 다음 틱에서 자신의 탐색 차례가 돌아왔을 때 그 거리부터 계속합니다. 사고 차량이 앞을 막은 경우 후진 한도 16m를 0.5m씩 검사하면 최대 32개 거리 후보가 됩니다. 예전처럼 이 전체를 한 콜백 안에서 검사하면 네트워크 입력을 처리할 기회를 오래 잃을 수 있습니다. 현재는 뒤쪽 안전 공간과 차선 조건을 매 단계 다시 확인합니다. 장애물 ID나 기준 위치가 바뀌면 커서를 초기화하므로 오래된 장면에 대한 계획을 그대로 이어 가지 않습니다. 0.5m는 실제 후진을 한 번에 순간이동하는 거리가 아니라 계획 중 가정하는 후보 간격이라는 점이 중요합니다.`,
  'npc', 'SimulationHost::begin_npc_escape_reverse', 547, 555);

code(5, '차량 전체의 순환식 탐색 차례',
  ['round-robin은 요청한 차량들이 차례로 계산 기회를 받게 하는 방식입니다.'],
  `후진 후보를 한 개로 줄여도 모든 NPC가 같은 틱에 비싼 탐색을 하면 전체 비용이 다시 커질 수 있습니다. 호스트는 차량 집합 전체에서 한 틱에 하나의 탐색 proposal만 선택합니다. 이 발췌는 요청 중이고 다른 변경 경로를 실행하지 않으며 운행 가능한 차량만 후보로 봅니다. 직전에 선택한 ID보다 큰 요청자 중 가장 작은 ID를 고릅니다. 뒤쪽 ID가 없으면 전체 요청자 중 가장 작은 ID로 돌아갑니다. 이것이 round-robin이며, 지속적으로 요청하는 작은 ID 한 대가 매번 선택되어 다른 차가 영원히 기다리는 기아를 막는 방법입니다. 한 proposal은 내부 후보 검사들을 포함하므로 CPU 시간 1ms 같은 절대 상한을 보장하지는 않습니다. 대신 차량 수와 후진 후보 수가 늘어도 한 틱에 수행할 상위 탐색 단위의 수를 제한합니다. 네트워크 콜백이 실행될 틈을 만들고 동일 입력에서 선택 순서를 재현하기 쉬운 구조입니다. 탐색하지 않는 차량도 위치 표현과 기본 추종 갱신까지 모두 멈춘다는 뜻은 아닙니다.`,
  'npc', 'SimulationHost::prepare_lane_npc', 1076, 1086, { imageKey: 'server_tick' });

code(5, '후진 탐색 예산을 검증하는 회귀 코드',
  ['실패 후보를 끝까지 소진하고 다시 요청하는 장면에서 공정성을 검사합니다.'],
  `회귀 테스트는 한 번 고친 오류가 다시 생기지 않도록 조건을 고정한 검사입니다. 이 테스트는 3대 NPC 앞에 사고 충돌체를 두고 옆으로 통과할 수 없는 좁은 도로와 충분한 후방 공간을 구성합니다. 성공 후보가 일찍 발견되는 쉬운 장면보다 실패를 반복하는 장면이 작업 예산을 확인하기 좋습니다. 발췌는 모든 NPC가 일정 횟수 이상 탐색했고 최대 후보 거리가 진행되었는지 검사합니다. full_search일 때는 각 차량이 16m까지 32개 후진 후보를 소진한 뒤 다시 탐색을 시작했는지도 요구합니다. 앞쪽 반복에서는 틱당 전체 search_steps 증가가 1 이하인지, 대기 차량의 커서가 몰래 변하지 않는지 확인합니다. 새 Play를 두 번 실행해 초기 25틱의 선택 순서가 같은지도 검사합니다. 긴 검사는 180틱입니다. 매 틱 신선한 입력을 공급하고 active 상태를 확인하므로 탐색 중 입력 안전 정지가 발생하는 회귀까지 함께 드러낼 수 있습니다.`,
  'budgettest', 'exercise_searches', 205, 210);

code(5, '시뮬레이션 시간에서 계산하는 신호 단계',
  ['주기 안의 현재 위치를 구하면 같은 시간에 같은 신호 단계를 선택할 수 있습니다.'],
  `신호 phase는 전체 주기 안에서 특정 이동 방향에 어떤 신호를 주는 한 구간입니다. TrafficNetwork::signals_at은 누적 시뮬레이션 시간과 신호 계획을 사용해 현재 단계를 구합니다. 발췌의 plan_cycle_ns는 ms 설정을 ns로 변환한 주기입니다. 나머지 연산으로 현재 시간이 주기 어디에 있는지 구하고 offset을 더한 뒤 다시 주기로 감쌉니다. 예를 들어 교육용 주기가 60초이고 offset이 5초라면 누적 67초에서 위치는 12초입니다. 다음 반복은 각 phase의 지속 시간을 누적해 이 위치가 속한 구간을 찾습니다. 시뮬레이션 시간을 쓰므로 같은 시간과 설정에서 같은 단계가 나옵니다. 하지만 안전 정지나 고장 시 표시 정책까지 모두 시간 나머지 연산 하나로 설명되지는 않습니다. 함수의 enabled 입력과 구조물 손상 후 개별 신호 상태 적용도 함께 봐야 합니다. 신호등 메시 한 개가 쓰러졌다는 사건과 전체 교차로 주기 시계가 멈추는 사건을 분리해서 조사하는 이유입니다.`,
  'traffic', 'TrafficNetwork::signals_at', 904, 915);

add(5, 'lesson', '도로 곡률과 방향지시 의도의 차이',
  ['일반 곡선 도로를 따라 도는 동작 자체는 교차로 좌·우회전 신호가 아닙니다.',
   '차선 변경·우회와 교차로 연결 방향은 별도로 방향지시 의도를 만듭니다.'],
  `차량의 현재 yaw가 변했다는 사실만으로 깜빡이를 켜면 곡선 도로를 따라갈 때도 방향지시등이 계속 켜질 수 있습니다. 현재 follower는 신호 그룹이 있는 접근 차선과 그다음 연결 차선을 살펴봅니다. 접근 끝 방향과 연결 차선 끝 방향의 차이가 기준을 넘는 경우에 교차로 좌회전 또는 우회전 의도를 반환합니다. 일반 곡선 차선에는 이 조건이 없으므로 단순한 도로 굽음은 의도 0입니다. 차선 변경이나 국소 우회는 별도 실행 상태가 방향지시 의도를 제공합니다. 이 분리는 조향각이라는 순간적인 물리 값과 주변 차량에게 알리고 싶은 행동 의도가 다르기 때문에 필요합니다. turn_signal_intent에서 반환값 0, 1, 2가 각각 무엇인지 직접 찾아보세요. 표시가 켜지지 않는 문제와 의도 자체가 잘못 생성된 문제도 분리할 수 있습니다. 이 구현은 도로 그래프의 신호 그룹과 연결 정보에 의존하므로 잘못 작성된 도로 데이터까지 자동으로 이해해 바로잡는 기능은 아닙니다.`,
  [ref('follower', 'NpcLaneFollower::turn_signal_intent', 425, 446), ref('npc', 'SimulationHost::prepare_lane_npc', 1311, 1328)]);

code(5, '정차 중 경로 회전을 막는 이동 거리 한도',
  ['경로 추종에 의한 방향 변화는 실제 이동 거리와 최소 회전 반경으로 제한합니다.'],
  `NPC가 정지했는데 차체만 남은 경로 방향으로 돌아가면 바퀴로 주행하는 차가 아니라 제자리 회전 장치처럼 보입니다. 이전 heading smoothing은 각속도와 각가속도를 부드럽게 만들었지만 정지 조건과 연결되지 않아 이러한 잔여 회전을 만들 수 있었습니다. 이 조각은 nominal_movement를 최소 회전 반경으로 나누어 이번 틱에 가능한 방향 변화의 한도를 만듭니다. 이동량이 거의 0이면 예산도 0입니다. 교육용으로 한 틱 0.01m를 움직이고 최소 반경이 5m라면 허용 방향 변화는 0.002rad, 약 0.115도입니다. 이동량이 작은 재출발에서도 곡률이 제한됩니다. 여기서 nominal은 경로 추종이 의도하는 움직임을 뜻합니다. 외부 충돌 충격으로 회전하는 각운동량은 아래쪽에서 별도로 처리하므로 정지차가 충돌해도 절대로 회전하지 못하게 만드는 규칙이 아닙니다. 미세한 움직임과 완전 정지를 따로 테스트해야 한쪽 조건만 통과하는 수정을 피할 수 있습니다.`,
  'npc', 'SimulationHost::prepare_lane_npc', 1301, 1306);

add(5, 'table', 'NPC 문제를 분류하는 관찰 항목',
  ['같은 정지 현상도 경로·충돌·복구·계산 대기 중 어느 원인인지 구별합니다.'],
  `NPC가 똑똑해졌다는 말보다 어느 입력을 보고 어떤 제한 안에서 판단하는지 설명하는 편이 정확합니다. 현재 판단의 근거는 서버 도로망과 충돌체, 신호 상태, 사고 후 복구 상태입니다. 운전석 카메라의 영상을 인식하거나 사람의 상식을 학습한 정책은 아닙니다. 도로 연결이 없거나 차체가 지나갈 공간이 없거나 후방이 막히면 기다리는 것이 현재 모델에서 맞는 결과일 수 있습니다. 반대로 공간이 있는데 계속 멈추면 obstacle 거리, 검색 요청 여부, reverse cursor가 진행하는지부터 확인하세요. 검색 차례를 기다리는 차량과 운행 불가 손상 차량을 같은 원인으로 묶으면 잘못된 수정을 하게 됩니다. 경로 추종은 가속도와 회전 반경을 제한한 축약 운동이며 플레이어의 엔진, 차동장치, 네 바퀴 슬립을 모두 계산하지 않습니다. 포트폴리오에서는 이 차이를 숨기기보다 계산량과 구현 범위를 선택한 근거로 설명할 수 있어야 합니다. 성공한 우회 영상과 통과할 수 없는 장면의 대기 로그를 함께 비교해 보세요.`,
  [ref('npc', 'SimulationHost::npc_navigation', 323, 349), ref('npc', 'SimulationHost::update_npc_navigation', 916, 1038)],
  { headers: ['관찰', '확인할 값', '가능한 원인'], rows: [
    ['경로를 못 고름', 'destination_lane_id', '연결·목적지 조건'],
    ['우회 시작 안 함', 'search_steps, cursor', '계산 차례·후보 실패'],
    ['사고 후 정지', 'recovery, avoidance_phase', '손상·복구·후방 공간'],
    ['정차 중 차체 회전', '이동량, nominal yaw', '추종 회전 한도'],
  ] });

add(6, 'lesson', '최근 stale 경고의 실제 원인',
  ['2026-09-08에는 NPC 후진 후보의 동기 탐색이 입력 처리까지 지연시켰습니다.',
   '시간 제한을 늘리지 않고 틱별 작업량을 나누어 원인을 줄였습니다.'],
  `stale은 현재 사용하기에 너무 오래되었다는 뜻입니다. 이 사례의 로그에서는 tick deadline miss가 61~63까지 늘고 마지막 제어 후 약 1036~1089ms에서 제어권이 만료되었습니다. 이는 인터넷이 느리다는 사실을 직접 증명하지 않습니다. 단일 메인 이벤트 루프 안에서 사고 장애물에 대한 최대 32개 후진 거리 후보를 동기 탐색하면, 운영체제가 받은 입력도 서버 콜백이 처리하지 못한 채 기다릴 수 있었습니다. 해결은 1000ms 기준을 늘리는 대신 커서와 차량 전체 round-robin으로 상위 탐색 작업을 나누는 것이었습니다. 작업 기록의 3대 스트레스 시험에서는 틱별 탐색 증가가 최대 1이었고 각 차량이 32개 후보를 끝까지 소진했습니다. 함께 기록된 최대 약 49.38ms는 실제 타이머 대기와 당시 실행 부하를 포함한 관측치입니다. 이를 모든 PC에서 60Hz를 보장한다는 뜻으로 해석하면 안 됩니다. 결정적인 작업 수 검증과 환경에 따라 달라지는 시간 측정을 구분하는 것이 이 사례의 핵심입니다.`,
  [ref('worklog', 'NPC', 175, 216), ref('budgettest', 'exercise_searches', 155, 218)],
  { imageKey: 'server_tick' });

add(6, 'table', '화면 재생과 물리 재실행의 구분',
  ['기록이라는 이름이 같아도 저장 대상과 검증 목적은 다릅니다.'],
  `Unreal의 USimCoreDriveReplayComponent는 받아들인 authoritative snapshot을 저장하고 화면에서 ghost로 다시 보여 줍니다. 주행 경로와 당시 표시를 확인하는 데 유용하지만 입력으로 물리식을 다시 풀어서 같은 결과가 나오는지를 증명하는 기능은 아닙니다. 서버 PhysicsReplayRecorder는 매 틱 입력, 외부 충돌 proxy, 차량 상태와 실행 정체성을 기록합니다. verify_physics_replay는 같은 물리 조건으로 다시 계산하여 저장된 상태와 비교합니다. 이때 교통 AI 전체를 두 번째로 실행하는 것이 아니라 기록된 외부 proxy를 사용해 ego 차량 물리를 검증합니다. 영상 파일은 화면을 기록하므로 두 데이터 기록과 다시 구별됩니다. 녹화에서 같은 장면이 보이는 것과 계산 재현성이 확인된 것은 다른 주장입니다. 어떤 버그를 다시 보고 싶은지에 따라 도구를 고르세요. 시각 애니메이션의 어색함은 화면과 snapshot 재생이 도움 되고, 차체 좌표가 달라지는 계산 회귀는 물리 기록과 오차 비교가 더 직접적인 근거가 됩니다.`,
  [ref('unreal/DriveIntegration/Source/DriveIntegration/SimCoreDriveReplay.h', 'USimCoreDriveReplayComponent', 52, 75),
   ref('replayh', 'PhysicsReplayIdentity', 14, 24), ref('replay', 'verify_physics_replay', 392, 404)],
  { headers: ['종류', '기록 대상', '주요 목적'], rows: [
    ['화면 영상', '렌더링된 화면', '보이는 문제 확인'], ['Unreal 주행 재생', '수신 상태', 'ghost 경로·표현 확인'],
    ['서버 물리 재생', '입력·proxy·정체성·결과', '같은 조건의 계산 비교'],
  ] });

code(6, '입력과 외부 충돌 상태를 남기는 코드',
  ['TICK에는 프레임 번호, 네 가지 입력, 기어, 충돌 proxy 수를 기록합니다.'],
  `이 함수는 물리 한 단계에 사용한 조건을 저장합니다. complete 또는 invalid 상태면 더 기록하지 않고, 먼저 입력을 검증합니다. proxy 수의 상한도 확인하므로 무제한 외부 물체를 조용히 받아들이는 형식이 아닙니다. output에는 TICK 표식과 프레임 번호, throttle, brake, steering, handbrake, gear를 순서대로 씁니다. 이어 외부 충돌체 개수를 기록한 뒤 각 proxy의 상세 정보를 별도 줄에 씁니다. 바로 아래에는 결과 상태를 기록하는 부분이 이어집니다. 입력만 저장하지 않는 이유는 다른 차량과 사람의 충돌 상태도 내 차의 결과에 영향을 주기 때문입니다. 같은 핸들 입력이라도 다른 위치의 NPC와 접촉하면 다음 위치는 달라집니다. 이 형식은 ego 물리를 재실행할 때 당시 외부 충돌 환경을 공급하는 목적입니다. 프레임 번호와 시뮬레이션 시간이 어떻게 대응하는지 설명해 보세요. 파일의 데이터를 읽을 때 입력 순서와 단위를 놓치면 실제로 다른 실험을 같은 실험이라고 비교하게 됩니다.`,
  'replay', 'PhysicsReplayRecorder::tick', 348, 359);

code(6, '물리 재생 전에 실행 조건을 확인하는 코드',
  ['빌드·설정·지도·시작 위치·주파수가 맞아야 같은 실험이라고 볼 수 있습니다.'],
  `결정성은 같은 조건에서 같은 결과를 얻는 성질입니다. 여기서 같은 조건에는 키 입력만 포함되는 것이 아닙니다. 실행 파일과 차량 설정, 지도, 초기 위치와 방향, 틱 주파수, 외부 충돌 상태도 포함됩니다. 발췌는 expected_identity를 먼저 검증하고 파일 형식 버전을 검사합니다. 다음 identity_line의 정확한 일치를 요구한 뒤 VehiclePhysics를 같은 원점과 시작 방향, 지면, 충돌 세계로 만듭니다. 숫자 표기를 정확하게 직렬화하는 이유는 서로 다른 설정을 비슷한 값이라며 통과시키지 않기 위해서입니다. 이후 각 틱 입력을 다시 적용하고 결과와 허용 오차를 비교합니다. 특정 빌드에서 오차 0을 얻었다고 해서 다른 컴파일러나 CPU, 모든 멀티스레드 순서에서도 자동으로 비트 단위 결정성이 보장되지는 않습니다. 무엇이 고정되었고 무엇이 기록되었는지를 함께 적어야 재현성 주장이 의미를 가집니다. 파일이 맞지 않아 거부되는 경우도 실험 조건을 지키는 정상적인 검증 결과입니다.`,
  'replay', 'verify_physics_replay', 396, 404);

add(6, 'table', '검증 수준과 증명할 수 있는 범위',
  ['테스트 통과는 그 테스트가 만든 조건과 검사 항목에 대한 증거입니다.'],
  `단위 테스트는 작은 함수나 모델의 경계를 빠르게 검사합니다. host 테스트는 세션과 틱, NPC를 연결해 여러 책임의 상호작용을 확인합니다. 통신 시험은 실제 소켓으로 입력과 상태가 오가는지 확인하고, Unreal 수동 인수는 화면과 조작감이 요구에 맞는지 확인합니다. 한 수준이 다른 수준을 완전히 대신하지는 않습니다. 회귀 100개가 통과해도 실제 연석 정지 자세를 구성한 시험이 없으면 그 자세의 구동력 소실은 놓칠 수 있습니다. 반대로 플레이가 부드럽다는 인상만으로 hard lease의 경계값이 맞다고 증명할 수도 없습니다. 테스트 이름을 읽은 뒤 준비한 상태, 실행한 행동, 비교한 결과를 세 칸으로 적어 보세요. 제일 중요한 질문은 무엇을 확인하지 않았는가입니다. 운영체제 스케줄링 영향을 받는 시간 상한과 결정적으로 계산할 수 있는 작업 수 상한도 구별하세요. 작업 수 회귀가 통과해도 실제 장면의 한 후보가 지나치게 비싸다면 별도의 측정과 개선이 필요할 수 있습니다.`,
  [ref('budgettest', 'exercise_searches', 155, 218), ref('coursetest', 'test_reported_diagonal_curb_restart', 550, 614),
   ref('replay', 'verify_physics_replay', 392, 430)],
  { headers: ['수준', '대표 확인', '남는 한계'], rows: [
    ['모델·단위', '공식·경계값', '실제 연결 순서'], ['호스트 통합', '제어권·NPC·고정 틱', '실제 소켓 환경'],
    ['통신·재생', '신선도·상태·오차', '화면·체감'], ['Unreal 인수', '조작·표현·장면', '모든 수치 경계'],
  ] });

add(6, 'lesson', '멈춤 현상을 조사하는 기록 순서',
  ['시각·위치·방향·입력·health·접촉·바퀴 하중을 같은 시점에 비교합니다.',
   '관찰값과 원인 가설을 구분하고 재현에 필요한 조건부터 줄입니다.'],
  `차가 안 움직인다는 보고에서 바로 마찰 계수를 바꾸면 원인을 덮을 수 있습니다. 먼저 서버가 active인지, throttle과 gear가 기대대로 들어오는지 확인하세요. 이어 위치와 heading, 선속도, 각속도, ground coverage, 접촉 수를 같은 시점으로 묶습니다. 바퀴별 Fz와 Fx를 보면 입력이 있어도 구동력이 지면으로 전달되지 않는지 구별할 수 있습니다. 연석 사례에서는 손상과 차체 접촉이 없는데 한쪽 후륜 하중이 거의 0이었고 양쪽 후륜 구동력이 작았습니다. 이 관측이 차동장치의 제한을 의심할 근거가 되었습니다. 그러나 Fz가 작다는 사실만으로 모든 멈춤을 같은 버그라고 결론내리면 안 됩니다. 완전한 지면 범위 이탈이나 중립 기어, 안전 정지도 별도 원인입니다. 재현 위치와 자세를 테스트에 고정한 뒤 수정 전후의 이동 거리와 최대 속도, 관통 여부를 함께 비교하세요. 화면 영상은 맥락을 제공하고 수치 로그는 가설을 검증합니다. 두 자료가 같은 시간의 사건인지 확인하는 습관이 필요합니다.`,
  [ref('host', 'SimulationHost::run_tick', 679, 700), ref('coursetest', 'test_reported_diagonal_curb_restart', 550, 614)]);

add(7, 'quiz', '실습 1: 현상에서 함수까지 찾기',
  ['코드를 고치지 않고 다섯 현상마다 첫 확인 함수와 이유를 적어 보세요.',
   '입력 정지, 지면 이탈, 후륜 구동 소실, 우회 지연, 물리 재생 불일치입니다.'],
  `이 실습의 목적은 전체 파일을 외우는 대신 책임 경계를 따라 필요한 코드를 찾는 것입니다. 15분 타이머를 설정하고 각 현상에 대해 첫 번째로 볼 함수 하나, 확인할 상태 값 두 개, 다음으로 이어 볼 함수 하나를 적으세요. 입력이 멈춘 경우에는 네트워크가 연결되어 있다는 정보만 주어졌다고 가정합니다. 지면 이탈은 차량의 일부 바퀴가 샘플 범위를 벗어난 경우입니다. 후륜 구동 소실은 throttle과 기어가 유효하지만 한쪽 후륜 Fz가 거의 0인 경우입니다. 우회 지연은 여러 사고 장애물 앞에서 연결 stale 경고도 함께 나타나는 상황입니다. 재생 불일치는 새 설정으로 바꾼 뒤 예전 기록을 검증하는 상황입니다. 검색창에 함수 이름을 직접 입력하고 조건 분기를 읽되 호출과 구현을 구별하세요. 답을 쓸 때 무조건 물리부터 본다는 식으로 넓게 쓰지 말고 비교할 값과 이유를 적어야 합니다. 다음 풀이를 보기 전에는 서버를 실행하거나 계수를 변경할 필요가 없습니다.`,
  [ref('lease', 'ControlLease', 114, 180), ref('phys', 'VehiclePhysics::update', 1094, 1109),
   ref('npc', 'SimulationHost::prepare_lane_npc', 1066, 1086), ref('replay', 'verify_physics_replay', 392, 404)]);

add(7, 'quiz', '실습 2: 속도·하중·마찰의 손계산',
  ['50km/h, 60Hz, 질량 1500kg, g=9.80665m/s², 전륜 정하중 55%를 사용합니다.',
   '틱 이동량, 앞·뒤 바퀴별 하중, μ=1에서 Fx=2000N일 때 남는 Fy를 구하세요.'],
  `먼저 단위를 적고 계산식을 쓰세요. 속도는 km/h를 m/s로 바꾼 뒤 dt를 곱해야 합니다. 질량 1500kg과 무게 N을 같은 값으로 놓으면 하중 계산이 틀립니다. 평평한 정지 상태이며 좌우가 대칭이고 공력과 가감속 하중 이동은 없다고 가정합니다. 앞바퀴 두 개가 전체 무게의 55%, 뒤바퀴 두 개가 45%를 나누어 받습니다. 마지막 마찰 문제는 계산을 분리하기 위해 한 바퀴 하중을 전체 무게의 4분의 1로 다시 가정합니다. μ=1, 종방향 힘 2000N일 때 마찰 원 안에 남는 횡방향 힘의 최대 크기를 구하세요. 추가로 L=2.7m, 앞바퀴 조향각 10도인 무슬립 교육용 자전거 모델의 반경과 50km/h에서 요구하는 횡가속도를 계산해 보세요. 실제 서버가 이 간단한 식만으로 차량을 회전시키는 것은 아닙니다. 교육식의 요구치가 접지 한계를 넘는지 판단하기 위한 문제입니다. 소수 둘째 자리 정도로 반올림하되 중간 계산은 너무 일찍 줄이지 마세요.`,
  [ref('suspension', 'evaluate_suspension', 43, 74), ref('phys', 'VehiclePhysics::update', 995, 1035)]);

add(7, 'answer', '실습 1·2 풀이와 자주 생기는 단위 오류',
  ['50km/h는 13.8889m/s이며 1/60초 동안 약 0.23148m 이동합니다.',
   '전륜 한 개 약 4045.24N, 후륜 한 개 약 3309.74N입니다.'],
  `실습 1의 시작점은 입력 정지에서 ControlLease의 update_timeout과 health, 지면 이탈에서 VehiclePhysics::update의 ground coverage 분기, 구동 소실에서 차동 토크와 Fz 계산입니다. 우회 지연은 prepare_lane_npc의 차례 선택과 begin_npc_escape_reverse의 커서, 재생 조건은 verify_physics_replay의 identity 비교부터 보세요. 함수 이름을 썼어도 실제 상태와 연결한 이유가 없으면 다시 보완하세요. 실습 2에서 무게는 1500×9.80665=14709.975N입니다. 앞바퀴 한 개는 여기에 0.55/2를, 뒤바퀴 한 개는 0.45/2를 곱합니다. 별도 대칭 하중 가정의 Fz는 3677.49375N이고 남는 Fy는 제곱근(3677.49375²−2000²)로 약 3086.1N입니다. 교육용 반경은 2.7/tan(10도)로 약 15.31m, 요구 횡가속도는 v²/R로 약 12.60m/s²입니다. μ=1의 g보다 크므로 무슬립 가정만으로 그 회전을 유지할 수 없습니다. rad와 도를 삼각함수에 잘못 넣는 실수도 점검하세요.`,
  [ref('lease', 'ControlLease', 155, 180), ref('phys', 'VehiclePhysics::update', 995, 1109),
   ref('npc', 'SimulationHost::prepare_lane_npc', 1066, 1086), ref('replay', 'verify_physics_replay', 392, 404)]);

add(7, 'quiz', '실습 3: 제어 만료와 탐색 예산 추론',
  ['마지막 수신 뒤 250ms·251ms·1000ms·1001ms에서 어떤 조건이 참인지 적으세요.',
   '3대가 계속 요청할 때 32개 후진 후보를 한 틱에 처리하면 안 되는 이유를 설명하세요.'],
  `시간 문제는 유효 제어권이 있고 설정이 soft 250ms, hard 1000ms이며 중간에 새 입력과 estop, 새 Play가 없다는 가정입니다. 각 시각에서 비교 조건이 참인지를 쓰고 실제 상태 변경은 해당 검사 함수가 실행될 때 생긴다는 점도 적으세요. 다음 문제는 server_elapsed 80ms와 client_elapsed 20ms인 명령, 그리고 각각 150ms와 20ms인 명령의 추정 queue age를 계산하는 것입니다. 나머지 검증 조건은 모두 통과했다고 가정합니다. 마지막으로 3대가 지속 요청하는 장면에서 round-robin ID 순서를 처음 9번 적으세요. 후보 간격은 0.5m이고 사고 후진 범위는 16m입니다. 한 proposal 안에도 여러 충돌 검사가 있다는 조건에서 틱당 proposal 최대 1이 의미하는 보장과 보장하지 못하는 내용을 각각 한 문장으로 쓰세요. 계산 대기 중인 NPC에게 안전하지 않은 후진을 강제로 허용하면 안 되는 이유도 생각해 보세요. 이 문제는 숫자 답뿐 아니라 공정성, 신선도, 안전 조건의 역할을 나누어 설명하는 연습입니다.`,
  [ref('lease', 'ControlLease', 123, 180), ref('npc', 'SimulationHost::prepare_lane_npc', 1072, 1086),
   ref('npc', 'SimulationHost::begin_npc_escape_reverse', 493, 558)]);

add(7, 'answer', '실습 3 풀이와 작업 수 보장의 의미',
  ['경계 비교는 초과 조건입니다. 250ms와 1000ms 정확히 일치할 때는 해당 만료가 아닙니다.',
   '추정 queue age는 각각 60ms와 130ms이며 100ms 제한에서는 뒤의 명령이 거부됩니다.'],
  `251ms에서는 soft 만료 조건이 참이어서 안전 입력을 적용할 수 있고, 1001ms에서는 hard 만료 조건이 참입니다. 1000ms에도 soft 기준은 이미 넘었지만 hard 기준은 아직 초과하지 않았습니다. 검사가 실행되는 틱과 타이머 스케줄 때문에 화면에 변화가 나타나는 시각이 경계값과 정확히 일치한다고 보장하지는 않습니다. queue age는 두 시계의 절대값을 빼지 않고 연속 명령 사이 서버 경과와 클라이언트 경과의 차이에서 양수 부분을 사용합니다. 예제의 60ms는 통과하고 130ms는 거부됩니다. 3대의 ID가 1001, 1002, 1003이면 첫 9개 차례는 이 순서를 세 번 반복합니다. 16/0.5=32개 후진 거리이며 첫 일반 탐색이나 제동 대기는 별도 단계가 될 수 있습니다. 틱별 하나라는 규칙은 상위 탐색 작업 수를 제한하고 연속 요청자에게 공정한 기회를 줍니다. 한 작업 내부 비용과 운영체제 부하가 일정하다는 보장은 아니므로 항상 16.67ms 안에 끝난다는 결론은 틀립니다.`,
  [ref('lease', 'ControlLease', 123, 180), ref('budgettest', 'exercise_searches', 155, 218)]);

add(7, 'lesson', '학습 범위와 다음 확인 기준',
  ['입력·시간·접지·충돌·NPC를 구분하고 실제 코드로 원인을 설명할 수 있으면 첫 목표를 달성한 것입니다.',
   '완전한 실차·인체·자율주행 시뮬레이터라는 표현은 현재 구현 범위를 넘습니다.'],
  `마지막에는 설명을 덮고 네 가지를 말해 보세요. 첫째, 입력이 있는데 차가 안 움직일 때 제어권 문제와 구동력 문제를 어떻게 구별하나요. 둘째, 조향각과 yaw가 왜 다른 값이며 고속에서 접지 한계가 결과를 어떻게 바꾸나요. 셋째, 같은 경로라도 NPC 우회 계산이 왜 통신 신선도에 영향을 줄 수 있나요. 넷째, 화면 재생과 같은 조건의 물리 재실행은 어떤 차이가 있나요. 막히는 질문은 해당 함수와 숫자 예제로 돌아가 한 페이지 요약을 다시 적으세요. 현재 차량 코어는 지면 접촉 중심의 축약 모델이고 NPC는 플레이어 네 바퀴 물리를 그대로 실행하지 않습니다. 오토바이 균형 보조와 충돌체 회전, 보행자 몸체 반응도 모든 실제 역학을 정확히 재현하는 모델은 아닙니다. 다음 학습에서는 C++ 객체 수명과 비동기 콜백, 선형대수의 좌표 변환, 힘과 충격량의 단위를 차례로 보완하면 좋습니다. 새 기능을 많이 외우는 것보다 작은 재현 장면을 만들고 근거를 들어 수정 결과를 설명하는 능력이 중요합니다.`,
  [ref('host', 'SimulationHost::run_tick', 628, 742), ref('phys', 'VehiclePhysics::update', 677, 700),
   ref('npc', 'SimulationHost::prepare_lane_npc', 1066, 1086), ref('replay', 'verify_physics_replay', 392, 404)]);

